window.CONTRACT=[{"code": "3-1-1", "ch": "Chapter 參　基本條款", "sec": "一、合約之前言（Preamble）", "title": "合約前言 Preamble 例一：採購與商標授權合約 (Buying Agent & Trademark)", "items": [{"k": "lead", "t": "厚厚的一份英文合約可以有上百條條款，但只要分類得當就能事半功倍。本單元先建立「主要條款 principal terms／一般條款 general terms」的分類觀念，再逐句精讀一份採購暨商標授權合約的前言（Preamble）：簽約日與當事人、WITNESSETH 與 WHEREAS 鑑於條款、以及 NOW, THEREFORE 的約因與同意。一句英文、一句中文對照，點句子可單句朗讀。"}, {"k": "h1", "t": "主要條款與一般條款", "ic": "📘"}, {"k": "p", "t": "主要條款（principal terms）：合約中規範核心事項之條款，也就是關於交易標的與交易條件的條款。例如貨物運送合約（freight agreement）中，運輸何種貨物、何時運輸、運費如何計算等，直接和貨物運輸之承攬本身有關者，都算主要條款。", "a": "6d7dab4006ce"}, {"k": "p", "t": "主要條款奠定一份英文合約的基礎。閱讀與理解主要條款已經超出英文文法本身的範疇——因為它直接針對交易本身；要準確判斷主要條款是否達成己方從事該筆交易的商業目的，閱讀者必須具備交易的背景知識。", "a": "907476a3856c"}, {"k": "p", "t": "一般條款（general terms）：合約中的輔助性條款。這並非說一般條款不如主要條款重要，而是任務與目的不同。最典型者如合約使用語言、應受管轄之法院、以及合約之準據法等。", "a": "dcda7b532fe6"}, {"k": "tip", "t": "讀合約先問兩句話：這條是在談**交易本身**（主要條款），還是在談**萬一有事怎麼辦／用什麼規則讀這份約**（一般條款）？分類對了，閱讀速度與風險判斷都會變快。", "a": "4cb8fb3d1939"}, {"k": "h1", "t": "合約前言（Preamble）的兩大功能", "ic": "📜"}, {"k": "p", "t": "合約文件的最前端，於第 1 條規定開始之前，除了標題與目錄之外，通常會有一定篇幅之前言。一般而言，合約前言通常有二種功能：㈠記載本交易及合約之目的；㈡記載雙方（或多方）當事人之名稱、地址以及在合約中之簡稱。", "a": "49333ad4fcfe"}, {"k": "h1", "t": "範例一・簽約日與當事人 (Parties)", "ic": "✍️"}, {"k": "en", "sp": "簽約日與當事人", "t": "THIS AGREEMENT signed on the 21st day of May, 2012 **by and between** ABC Limited, a Hong Kong Company, **having an office at** [address, Hong Kong] (**hereinafter referred to as** \"ABC HK\") and DEF Limited, having an office at [address, Taiwan] (hereinafter referred to as \"Manufacturer\").", "zh": "本合約係於 2012 年 5 月 21 日，由 ABC Ltd.（一香港公司，且其營業所位於〔地址〕，以下簡稱 ABC HK）及 DEF Ltd.（主營業所位於我國，地址為〔地址〕，以下簡稱生產者）所共同簽訂。", "a": "4d4fd5415e2b"}, {"k": "tip", "t": "前言第一段固定三件事：**簽約日**（signed on the 21st day of May, 2012）、**當事人全名與屬性**（a Hong Kong Company）、**地址與簡稱**（having an office at…；hereinafter referred to as…）。簡稱一旦定義，全約再出現 \"Manufacturer\" 就只指 DEF Limited。"}, {"k": "h1", "t": "WITNESSETH 與 WHEREAS 鑑於條款 (Recitals)", "ic": "🔎"}, {"k": "en", "sp": "立約見證", "t": "WITNESSETH", "zh": "**茲證明**（立約見證如下）：", "a": "d0301b58b43a"}, {"k": "en", "sp": "鑑於 ①", "t": "**WHEREAS** Manufacturer is engaged in the manufacturing of clothes and accessories (the \"Products\");", "zh": "鑑於生產者係從事衣服及配件的生產（以下合稱「產品」）；", "a": "3ad09c1d4b48"}, {"k": "en", "sp": "鑑於 ②", "t": "**WHEREAS** ABC HK is an indirect, **wholly-owned subsidiary** of ABC Company (\"ABC\"), which is located in the United States of America;", "zh": "鑑於 ABC HK 是 ABC Company（以下簡稱 ABC）所間接但完全所有的子公司，其所在地在美國；", "a": "58e32a265908"}, {"k": "en", "sp": "鑑於 ③", "t": "**WHEREAS**, ABC HK has the home office located at [address] and its representative offices located in other jurisdictions and engaged in product sourcing and other supply chain activities;", "zh": "鑑於 ABC HK 係指其主營業所位在〔地址〕，且其代表處位在其他國家，且從事生產外包及供應之業務；", "a": "c5a89deac594"}, {"k": "en", "sp": "鑑於 ④", "t": "WHEREAS, ABC HK is engaged in the **procurement** of Products **on behalf of** ABC and its affiliates, as **buying agent**;", "zh": "鑑於 ABC HK 係負責為 ABC 及其他子公司負責採購「產品」之**採購代理人**；", "a": "eae021c9e143"}, {"k": "en", "sp": "鑑於 ⑤", "t": "WHEREAS ABC identifies its Products by means of certain trade names, service marks, trademarks, logos, emblems, and indicia of origin, including the trademarks, the trade name ABC, all related applicable logos, emblems or symbols, and all combinations, forms and **derivatives thereof**, as are **from time to time** used by ABC or any of its affiliates, **whether registered or unregistered** (the \"Trademarks\"); and", "zh": "鑑於 ABC 係透過特定的商業名稱、服務標章、商標、標記，以及其他來源的指示（包括 ABC 的商標及商業名稱，以及所有由 ABC 及其他子公司所不時使用之相關的標記、標章或其他符號，或前揭之任何組合形式或衍生體等，而無論是否有註冊）（以下簡稱「商標」）來特定其「產品」；且", "a": "d0dcad70c1f2"}, {"k": "en", "sp": "鑑於 ⑥", "t": "**WHEREAS**, all Trademarks are owned by ABC, certain of which Trademarks will be used by and licensed to Manufacturer **pursuant to** this Agreement;", "zh": "且鑑於所有的「商標」係由 ABC 所擁有，但若干「商標」會授權予生產者依本合約使用。", "a": "8a9d4816de01"}, {"k": "tip", "t": "WHEREAS 子句不是在下義務，而是在**交代背景與交易動機**（recitals）。實務上它會影響日後的解釋（當條文有歧義時，法院會回頭看前言的交易目的），所以不要當裝飾品亂寫。"}, {"k": "h1", "t": "NOW, THEREFORE 約因與同意", "ic": "✅"}, {"k": "en", "sp": "據此約定", "t": "NOW, THEREFORE, **in consideration of** the **mutual covenants herein contained**, **the parties hereby agree as follows**:", "zh": "據此，以其下相互之約定為對價，雙方當事人同意下列事項：", "a": "0e55c851de03"}, {"k": "tip", "t": "NOW, THEREFORE 是前言與本文的**分水嶺**：上面是背景（WHEREAS），下面才是權利義務。in consideration of＝以…為對價（英美法的 consideration／約因），mutual covenants＝相互的約定。"}, {"k": "h1", "t": "書中解說：用語怎麼讀", "ic": "💡"}, {"k": "p", "t": "於上例中，第一段即載明雙方當事人之全名及地址。其下另外說明當事人與其母公司之法律關係以及公司之性質，並表明 ABC 公司之商標使用權。", "a": "1b9382362e59"}, {"k": "p", "t": "「Witnesseth」與「Whereas」一詞類似於中文之「鑑於」之意思，用來解釋若干基本需先行說明之事項。「Whereas」之後則列舉一些雙方當事人或本件交易之基本資訊。", "a": "41274a91436b"}, {"k": "p", "t": "於商標段落的「all combinations, forms and derivatives thereof」，其「thereof」就代表同段中的「certain trade names, service marks, trademarks, logos, emblems, and indicia of origin, including the trademarks, the trade name ABC, all related applicable logos, emblems or symbols」，意思就是這些商標或標章等的任何組合、形式或衍生體「combinations, forms and derivatives」。", "a": "2e9997c911f9"}, {"k": "p", "t": "特定用語（例如 Manufacturer、Product、Trademark）會以開頭大寫英文字母呈現，這代表本合約之中如果有使用到這些用語時，就代表在本段文字中所特定之文義（例如 Manufacturer 即代表係 DEF Ltd. 公司）。", "a": "6ca41529285d"}, {"k": "voc", "v": [{"w": "by and between", "pos": "prep. phr.", "zh": "由…雙方（共同簽訂）", "syn": "between（兩方）／among（三方以上）", "tip": "兩造用 by and between，三方以上習慣用 by and among。by 指作成行為的人，between 指當事人之間，合在一起是英美合約的慣用贅語。", "trap": "", "a": "23a2d73298bf", "az": "96a2a65bb285"}, {"w": "hereinafter referred to as", "pos": "phr.", "zh": "以下簡稱為", "syn": "(the \"Vendor\")／hereinafter called", "trap": "簡稱一旦定義，全約就只能是這個意思；審約時務必回頭確認每個簡稱**只被定義一次**，且與簽約頁、附件名稱一致。", "tip": "", "a": "e11140c6a238", "az": "548dcb100c8b"}, {"w": "having an office at", "pos": "phr.", "zh": "營業所設於", "syn": "having its registered office at（註冊營業所）", "tip": "registered office（註冊地）與 principal place of business（主營業所）在管轄與送達上效果不同，別混用。", "trap": "", "a": "74913cba25ea", "az": "d512183031bf"}, {"w": "WITNESSETH", "pos": "v.（古體）", "zh": "茲證明；立約見證", "tip": "witness 的古體第三人稱形式，現代合約常直接省略或改寫為 \"RECITALS\"。看到它＝下面要開始交代背景了。", "syn": "", "trap": "", "a": "d0301b58b43a", "az": "b6f14f5e4834"}, {"w": "WHEREAS", "pos": "conj.", "zh": "鑑於", "syn": "Recitals／Background", "trap": "WHEREAS 條款原則上**不創設義務**；若要產生拘束力，必須把內容寫進本文條款，或在本文加一句 \"The recitals form an integral part of this Agreement.\"。", "tip": "", "a": "c1f481b29cf7", "az": "a974650e10d6"}, {"w": "be engaged in", "pos": "v. phr.", "zh": "從事（某業務）", "syn": "carry on the business of", "tip": "前言描述當事人業務的固定句型：Manufacturer is engaged in the manufacturing of…", "trap": "", "a": "da01a28e4e45", "az": "ec2a56b44aa9"}, {"w": "wholly-owned subsidiary", "pos": "n. phr.", "zh": "完全持股之子公司", "syn": "100%-owned subsidiary", "tip": "indirect, wholly-owned＝間接但完全持有（中間還隔著其他公司）。", "trap": "", "a": "3eb77c6f29dd", "az": "20290e8385e4"}, {"w": "affiliates", "pos": "n.", "zh": "關係企業；關係人", "syn": "associated companies／group companies", "trap": "affiliate 的定義欄位常被忽略；若未定義，範圍可能擴及整個集團，連帶把保密、授權或競業範圍放大。", "tip": "", "a": "0d33899b65e9", "az": "a16508851141"}, {"w": "procurement", "pos": "n.", "zh": "採購", "syn": "sourcing／purchasing", "tip": "product sourcing＝生產外包／尋找貨源；supply chain activities＝供應鏈業務。", "trap": "", "a": "9a87ac582f0b", "az": "6e9937c08dfc"}, {"w": "on behalf of", "pos": "prep. phr.", "zh": "代表…；為…之利益", "syn": "for and on behalf of", "trap": "代理人以 on behalf of 簽約，法律效果歸本人；審約時要確認代理權限（authority）與簽名欄位是否一致。", "tip": "", "a": "73c09d012937", "az": "3e31cf0c2aa9"}, {"w": "buying agent", "pos": "n. phr.", "zh": "採購代理人", "tip": "本例的交易結構：ABC HK 是代理人，Manufacturer 是製造商，ABC 是品牌與商標權人。", "syn": "", "trap": "", "a": "33657c0f1115", "az": "29d18fb071da"}, {"w": "trade name / service mark / trademark", "pos": "n. phr.", "zh": "商業名稱／服務標章／商標", "tip": "三者是不同的識別標的：trade name 指公司或營業名稱，service mark 用於服務，trademark 用於商品。", "syn": "", "trap": "", "a": "2ee760585e65", "az": "a0469e79e137"}, {"w": "indicia of origin", "pos": "n. phr.", "zh": "來源之指示（識別標記）", "tip": "indicia 是 indicium 的複數，泛指足以指示商品來源的一切標記，用來把保護範圍寫寬。", "syn": "", "trap": "", "a": "8d986e256137", "az": "e42904f8c483"}, {"w": "derivatives thereof", "pos": "n. phr.", "zh": "其衍生體", "syn": "derivatives of the foregoing", "trap": "thereof＝of that／of the foregoing，指**前面剛提到的那串東西**；寫錯指涉對象會讓授權範圍失焦（書中特別解說此點）。", "tip": "", "a": "350270a81c07", "az": "0dc6632e9e40"}, {"w": "from time to time", "pos": "adv. phr.", "zh": "不時地；隨時（視情況）", "trap": "不是「偶爾」。它表示「於各該時點有效的版本」，常與 as amended from time to time 併用，等於把未來修改也包進來。", "syn": "", "tip": "", "a": "0e3e42e75011", "az": "41cc85f4e85b"}, {"w": "whether registered or unregistered", "pos": "phr.", "zh": "無論是否經註冊", "tip": "把未註冊商標也納入保護，是品牌方最在意的一句。", "syn": "", "trap": "", "a": "08781fedc07a", "az": "d9f4edff29d6"}, {"w": "pursuant to", "pos": "prep.", "zh": "依照；依據", "syn": "in accordance with／under", "tip": "pursuant to this Agreement＝依本合約。正式用語，口語不要用。", "trap": "", "a": "18dbc0e36ea6", "az": "827e55fc9326"}, {"w": "in consideration of", "pos": "prep. phr.", "zh": "以…為對價（約因）", "syn": "in consideration of the mutual covenants", "trap": "英美法下沒有 consideration 契約可能不成立；中文直譯成「考慮到」就錯了，它是**對價**。", "tip": "", "a": "5c4d9beba753", "az": "dfb0749ec1ef"}, {"w": "mutual covenants herein contained", "pos": "n. phr.", "zh": "本合約所載之相互約定", "tip": "covenant＝（契約上的）約定、承諾；herein contained＝本約所載。", "syn": "", "trap": "", "a": "a66821c899e6", "az": "0fca8fce3b9a"}, {"w": "the parties hereby agree as follows", "pos": "phr.", "zh": "當事人茲同意如下", "tip": "hereby＝以此（文件）；這句之後開始就是正式條文。", "syn": "", "trap": "", "a": "561eef75a6af", "az": "5455e067a236"}]}]}, {"code": "3-1-2", "ch": "Chapter 參　基本條款", "sec": "一、合約之前言（Preamble）", "title": "合約前言 Preamble 例二：股權買賣合約 (Vendor / Purchaser)", "items": [{"k": "lead", "t": "例二換成另一種常見結構：股權買賣（share sale and purchase）。書中點出它與例一的差別——「將合約當事人之名稱與註冊地址以並列之方式呈現，較為清楚」：簽約日單獨一句，再以 BETWEEN…AND… 分段列出雙方，並標明設立地與公司註冊號碼；WHEREAS 用 (a)–(g) 編號逐項鋪陳標的公司、唯一資產、股本、所有權、股東貸款資本化與待售股份。一句英文、一句中文對照精讀。"}, {"k": "h1", "t": "簽約日與當事人 (Parties)", "ic": "✍️"}, {"k": "en", "sp": "簽約日", "t": "THIS AGREEMENT **is made on** October 28th, 2012.", "zh": "本合約係於 2012 年 10 月 28 日所作成，於下列當事人間所成立：", "a": "3c1e561a5f84"}, {"k": "en", "sp": "賣方", "t": "BETWEEN A PTE. Limited, a company **incorporated in** the Republic of Singapore (**company registration number** xxxxxxx) and having its **registered office** at [address] (the \"Vendor\")", "zh": "A PTE Ltd.，係依新加坡法成立的公司（註冊號碼為：xxxxxxx），且其註冊主營業所位於〔地址〕（以下簡稱「賣方」）", "a": "c6982ea88f9f"}, {"k": "en", "sp": "買方", "t": "AND B Limited, a company **incorporated in** Taiwan, Republic of China (**company registration number** xxxxxxx) and having its **registered office** at [address] (the \"Purchaser\").", "zh": "及 B Ltd.，係依我國法成立的公司（註冊號碼為：xxxxxxx），且其註冊主營業所位於〔地址〕（以下簡稱「買方」）。", "a": "16a67614d0dd"}, {"k": "tip", "t": "例二比例一多寫了兩項關鍵資訊：**incorporated in（設立地）** 與 **company registration number（公司註冊號碼）**。跨境交易中設立地決定公司的能力與代表權，註冊號碼才是唯一識別；registered office 則是法定送達地址。書中的評語是：這種把名稱與註冊地址**並列**呈現的方式比較清楚。"}, {"k": "h1", "t": "WHEREAS 鑑於條款 (a)–(g)", "ic": "🔎"}, {"k": "en", "sp": "鑑於", "t": "WHEREAS:", "zh": "鑑於：", "a": "4ebed35c3148"}, {"k": "en", "sp": "(a) 標的公司", "t": "(a) C PTE. LTD. (the \"Company\") is a **private company limited by shares** incorporated in the Republic of Singapore (**Company registration number** xxxxxxx) and having its **registered office** at [address].", "zh": "㈠ C PTE. Ltd.（以下稱「標的公司」）係一**私營的股份有限公司**，於新加坡所設立（註冊號碼為：xxxxxxx），且其註冊主營業所位於〔地址〕。", "a": "85d33fcf72c8"}, {"k": "en", "sp": "(b) 唯一資產", "t": "(b) The **sole asset** of the Company is its investment in D Ltd., which **operates a factory** in [place] in the People's Republic of China (\"PRC\").", "zh": "㈡「標的公司」之**唯一資產**為其於 D Ltd. 之投資，後者係在中華人民共和國之〔某處〕**營運一工廠**。", "a": "28be6ede4f88"}, {"k": "en", "sp": "(c) 股本", "t": "(c) The Company has a **share capital** of 2 **ordinary shares**, all of which are **issued and fully paid** at the date of this Agreement.", "zh": "㈢「標的公司」總共有**普通股**票共二股，且在本合約簽訂時，皆已經全部發行及認足。", "a": "d6687a64309c"}, {"k": "en", "sp": "(d) 所有權", "t": "(d) The Vendor is the **registered and beneficial owner** of the 2 ordinary shares **representing 100% of** the issued and **paid-up share capital** of the Company.", "zh": "㈣「賣方」係前揭「標的公司」二股（亦即代表「標的公司」之百分之百發行及認購之股份）之註冊及受益人。", "a": "08829ef1be49"}, {"k": "en", "sp": "(e) 貸款資本化", "t": "(e) The Vendor **intends to capitalize** US$81,526,793 of its **shareholders loan** into 81,526,793 ordinary shares of the Company **by Completion Date**.", "zh": "㈤「賣方」欲**於「完成日」**，將其對「標的公司」價值美金 81,526,793 元之貸款，轉換為「標的公司」之 81,526,793 **普通股**。", "a": "e56d299e6315"}, {"k": "en", "sp": "(f) 待售股份", "t": "(f) **At Completion**, the Company will have US$81,526,793 **issued and fully paid**-up **ordinary shares** (\"Sale Shares\").", "zh": "㈥ **於「完成日」**時，「標的公司」將擁有 81,526,793 股已發行且認購完成之**普通股**（以下稱「**標的股份**」）。", "a": "6a1e05516acf"}, {"k": "en", "sp": "(g) 買賣意思", "t": "(g) The Purchaser desires to purchase and Vendor desires to sell the **Sale Shares** **on the terms and subject to the conditions set forth in this Agreement**.", "zh": "㈦「買方」希望購買以及「賣方」希望賣出的「**標的股份**」，**其條件依本約所載之條款**。", "a": "deab271df0dd"}, {"k": "tip", "t": "這七項 WHEREAS 其實是一張**盡職調查地圖**：標的公司是誰(a)、它值錢的東西是什麼(b)、股本結構(c)、賣方真的有權賣嗎(d)、交割前要先做什麼動作(e)、做完之後股權長什麼樣(f)、雙方的買賣意思(g)。審約時逐項回去要文件驗證。"}, {"k": "tip", "t": "⚠ 書上 (f) 的英文印成 \"US$81,526,793 issued and fully paid-up ordinary shares\"，但對照中譯是「81,526,793 **股**」——股數不該掛幣別符號。這正是實務上最常見的打字錯誤：**數字＋單位（股／元）寫錯**。審約時務必把英文與中文、金額與股數逐一核對。"}, {"k": "h1", "t": "NOW THEREFORE 與第一條", "ic": "✅"}, {"k": "en", "sp": "據此約定", "t": "NOW THEREFORE, in consideration of the mutual agreements, representations, warranties and subject to the conditions contained herein, **the parties hereto** hereby agree as follows:", "zh": "是故，以相互之協議、表述、保證以及下列之條件作為對價，當事人據此以本合約同意下列事項：", "a": "0d8e5ccd05ba"}, {"k": "en", "sp": "第1條", "t": "Definitions and Interpretation", "zh": "定義及解釋", "a": "3765df4fe52b"}, {"k": "tip", "t": "注意例二的 NOW THEREFORE 比例一多列了 **representations（表述／陳述）** 與 **warranties（保證）**——這是股權買賣的靈魂：賣方對標的公司的狀況做陳述與保證，不實時買方可請求損害賠償。接著第一條就是 **Definitions and Interpretation（定義及解釋）**，也就是下一單元的主題。"}, {"k": "h1", "t": "書中解說", "ic": "💡"}, {"k": "p", "t": "上述合約前言呈現的方式與前一例大同小異，差別在於本例中，將合約當事人之名稱與註冊地址以並列之方式呈現，較為清楚。", "a": "75bbf7a952ea"}, {"k": "p", "t": "「Whereas」也是相當於中文的「鑑於」之意思，其後則列舉一些雙方當事人或本件交易之基本資訊。", "a": "d54f333ea86d"}, {"k": "voc", "v": [{"w": "is made on", "pos": "v. phr.", "zh": "係於…所作成（簽訂）", "syn": "is entered into on／dated as of", "tip": "效力起算日有時與作成日不同，可寫成 \"made on … with effect from …\" 分開表示。", "trap": "", "a": "ad806ab890de", "az": "53912a05b684"}, {"w": "incorporated in", "pos": "v. phr.", "zh": "於…設立（登記成立）", "syn": "organized under the laws of", "trap": "設立地決定公司的**屬人法**（能力、代表權、股東權）；與營業地、稅籍地可能都不同，不要混為一談。", "tip": "", "a": "becbd494d9a6", "az": "3556636ef0d6"}, {"w": "company registration number", "pos": "n. phr.", "zh": "公司註冊號碼", "syn": "company number／統一編號", "tip": "同名公司很多，註冊號碼才是唯一識別。審約必與公司登記謄本核對。", "trap": "", "a": "0ac38178c1f8", "az": "812e79d829ed"}, {"w": "registered office", "pos": "n. phr.", "zh": "註冊（主）營業所", "syn": "registered address", "trap": "是法定**送達地址**，不等於實際辦公處所（principal place of business）；通知條款（Notices）要寫清楚寄哪一個。", "tip": "", "a": "c6e8a915b80a", "az": "9ed9c0775b9e"}, {"w": "Vendor / Purchaser", "pos": "n.", "zh": "賣方／買方", "syn": "Seller／Buyer", "tip": "不動產與股權交易慣用 Vendor/Purchaser；一般貨物買賣慣用 Seller/Buyer。", "trap": "", "a": "ffab55a9bb86", "az": "7c4e547b73b2"}, {"w": "private company limited by shares", "pos": "n. phr.", "zh": "私營的股份有限公司", "tip": "英、港、星公司法用語；private＝股份轉讓受限、不得公開募集。", "syn": "", "trap": "", "a": "6270704681bf", "az": "a0c600daa2ec"}, {"w": "sole asset", "pos": "n. phr.", "zh": "唯一資產", "tip": "本例 (b)：唯一資產是對 D Ltd. 的投資，而 D Ltd. 在中國營運一工廠——實質上買的是那座工廠的持股鏈。", "syn": "", "trap": "", "a": "ee81cd9dd799", "az": "b64879867296"}, {"w": "operates a factory", "pos": "v. phr.", "zh": "營運一工廠", "syn": "runs／carries on a manufacturing plant", "tip": "盡職調查要往下一層查 D Ltd.：土地廠房、環保、勞動、關係人交易。", "trap": "", "a": "cdf4eb6daeea", "az": "65e957152f26"}, {"w": "share capital", "pos": "n. phr.", "zh": "股本", "syn": "issued share capital（已發行股本）／paid-up share capital（實收股本）", "trap": "authorized（授權）≠ issued（已發行）≠ paid-up／fully paid（繳足）。三個數字不同，審約要逐一確認。", "tip": "", "a": "6244c952407a", "az": "ca392fafeb0c"}, {"w": "ordinary shares", "pos": "n. phr.", "zh": "普通股", "syn": "common stock（美式）／preference shares（優先股）", "tip": "a share capital of 2 ordinary shares＝股本總共只有兩股，典型的控股用 SPV。", "trap": "", "a": "bedbba397b48", "az": "15538f9bc985"}, {"w": "issued and fully paid", "pos": "adj. phr.", "zh": "已（全部）發行及認足", "trap": "若有未繳足（partly paid）股份，買方可能承受補繳義務；這是股權買賣的常見地雷。", "syn": "", "tip": "", "a": "69602fcb7e92", "az": "44b52bfd99f2"}, {"w": "registered and beneficial owner", "pos": "n. phr.", "zh": "註冊（登記）名義人及受益人", "trap": "兩者分離就是**借名登記／信託**。只確認 registered owner 不夠，必須同時確認 beneficial ownership，否則買到有爭議的股權。", "syn": "", "tip": "", "a": "e0a7899fba06", "az": "b7c8b1102621"}, {"w": "representing 100% of", "pos": "v. phr.", "zh": "代表百分之百之…", "tip": "用來說明該批股份占全部已發行且繳足股本的比例，等於保證買下去就是全資。", "syn": "", "trap": "", "a": "2e54498e7a9d", "az": "550302a7dd8b"}, {"w": "paid-up share capital", "pos": "n. phr.", "zh": "已認購（實收）之股本", "syn": "paid-in capital", "tip": "issued and paid-up share capital＝已發行且已繳足的股本。", "trap": "", "a": "403cf0108df5", "az": "71f7b9d587b1"}, {"w": "intends to capitalize", "pos": "v. phr.", "zh": "欲將…資本化", "syn": "debt-to-equity conversion（債轉股）", "tip": "手法：capitalize US$81,526,793 of its shareholders loan **into** 81,526,793 ordinary shares——把債權換成股權，交割時買方一次買下乾淨的股權。", "trap": "", "a": "fbf2118ef6fa", "az": "003c816f6323"}, {"w": "shareholders loan", "pos": "n. phr.", "zh": "股東貸款（股東借款）", "trap": "股東貸款若不先資本化或清償，交割後仍是公司對原股東的負債；價金計算與財務報表都會受影響。", "syn": "", "tip": "", "a": "3e10bee3142a", "az": "0200323af73a"}, {"w": "by Completion Date", "pos": "prep. phr.", "zh": "於「完成日」（交割日）前", "syn": "by Closing（美式）", "tip": "Completion／完成日是股權交易的核心時點：前有 conditions precedent（先決條件），後有 post-completion covenants。", "trap": "", "a": "991b3f20360f", "az": "872a7d940db7"}, {"w": "At Completion", "pos": "prep. phr.", "zh": "於完成（交割）時", "tip": "與 by Completion Date（在完成日前完成某動作）語意不同，前者描述交割當下的狀態。", "syn": "", "trap": "", "a": "8c6ad4a6ec85", "az": "7f7d67a20308"}, {"w": "Sale Shares", "pos": "n. phr.", "zh": "標的股份（待售股份）", "tip": "括號定義一出現，後面所有條文的「股份」就只指這一批。", "syn": "", "trap": "", "a": "4121ca7a5cfa", "az": "0b43e6469fe0"}, {"w": "desires to purchase / desires to sell", "pos": "v. phr.", "zh": "希望購買／希望賣出", "syn": "has agreed to sell／wishes to acquire", "tip": "WHEREAS 最後一項固定表明雙方的交易意思，承接下文 NOW THEREFORE。", "trap": "", "a": "952391cea3a9", "az": "aec56b8c9d12"}, {"w": "on the terms and subject to the conditions set forth in this Agreement", "pos": "phr.", "zh": "其條件依本約所載之條款", "trap": "terms（條款內容）與 conditions（條件；不成立則效力受影響）在英美法上效果不同，這組並列句是為了兩面都綁住。", "syn": "", "tip": "", "a": "befcc5de305d", "az": "6648496bdbe7"}, {"w": "representations and warranties", "pos": "n. phr.", "zh": "表述（陳述）與保證", "trap": "兩者救濟不同：representation 不實走 misrepresentation（可能撤銷契約），warranty 不實走違約損害賠償。股權買賣最核心的攻防就在這一欄。", "syn": "", "tip": "", "a": "07fa0f32f10f", "az": "df22c61813f1"}, {"w": "the parties hereto", "pos": "n. phr.", "zh": "本合約之當事人", "syn": "the parties to this Agreement", "tip": "hereto＝to this Agreement。與 hereof（of this Agreement）、herein（in this Agreement）、hereunder（under this Agreement）成套記。", "trap": "", "a": "58e2e2058390", "az": "9c0f58b06475"}, {"w": "Definitions and Interpretation", "pos": "n. phr.", "zh": "定義及解釋", "tip": "英文合約第一條的標準標題：先定義用語，再規定解釋規則。", "syn": "", "trap": "", "a": "3765df4fe52b", "az": "bcd956528ee7"}]}]}, {"code": "3-2-1", "ch": "Chapter 參　基本條款", "sec": "二、定義條款（Definition）", "title": "定義條款 Definition：把名詞釘死，條文才有意義", "items": [{"k": "lead", "t": "定義條款通常是英文合約的第一條，也是最容易被跳過、卻最常出事的一條。它把合約中反覆出現的專有名詞一次定義清楚，之後凡以開頭大寫出現，就只指這個意思。本單元讀書上的說明，以及 \"Accounts\"、\"Accounting Date\" 兩個互相引用的會計類定義範例。"}, {"k": "h1", "t": "為什麼要有定義條款", "ic": "📘"}, {"k": "p", "t": "於篇幅較長、內容複雜或專有名詞較多的英文合約，常常會設計一條（或專節）定義條款，內容是規定在本合約中使用的專有名詞的定義和解釋（Definitions and Interpretation）。", "a": "408b04542d71"}, {"k": "p", "t": "通常會在英文合約第一條或第一節，但是有些合約也會把定義條款放在合約的最後一條或最後一節，以避免整份文件頭重腳輕。", "a": "2918091c94df"}, {"k": "p", "t": "經定義之用語，於合約中使用時會以開頭大寫之英文字母呈現（例如 Manufacturer、Product、Trademark、Accounts），這代表本合約之中如果有使用到這些用語時，就代表在定義條款中所特定之文義。", "a": "4dcf20d50238"}, {"k": "tip", "t": "審約口訣：**看到大寫就回頭查定義**。很多爭議不是出在義務條文寫錯，而是定義被悄悄寫寬或寫窄（例如 Affiliates、Confidential Information、Territory、Net Sales）。另外也要記得**往後翻**——定義條款不一定在第一條，有些合約擺在最後。", "a": "61dcb7eefcd0"}, {"k": "h1", "t": "範例・定義條款的引導句", "ic": "✍️"}, {"k": "en", "sp": "引導句", "t": "In this Agreement, **unless the contract otherwise requires**, the following expressions **shall have the meaning set out against them**:", "zh": "於本合約中，**除非合約另有約定**，下列名詞**應具有下述所載之意義**：", "a": "4dda70216349"}, {"k": "tip", "t": "引導句的三個固定零件：**範圍**（In this Agreement）＋**例外**（unless the contract otherwise requires，除非合約另有約定）＋**效力**（shall have the meaning set out against them，應具有下述所載之意義）。實務上更常見的寫法是把 contract 換成 context：**unless the context otherwise requires**（除依上下文另有所指外）——兩種都要看得懂。"}, {"k": "h1", "t": "範例・定義 (a) Accounts、(b) Accounting Date", "ic": "📊"}, {"k": "en", "sp": "定義 (a)", "t": "(a) \"Accounts\" means the **audited financial statement** comprising the balance sheet, the **profit and loss account** and the **cash flow statement** of XYZ as of the Accounting Date;", "zh": "㈠「會計帳目」意指就 XYZ 公司於「審計日」經審計之財務報表，包括其**資產負債表**、**損益表**以及**現金流量表**；", "a": "0d67e35eaa50"}, {"k": "en", "sp": "定義 (b)", "t": "(b) \"Accounting Date\" means **with respect to** XYZ, the date of such Accounts for **the financial year ended 31 December 2012**;", "zh": "㈡「審計日」意指就 XYZ 公司，**於 2012 年 12 月 31 日所終止之會計年度**之「會計帳目」之日期；", "a": "97951379518c"}, {"k": "en", "sp": "定義 (c)", "t": "(c) \"Completion Date\" shall have the meaning specified in Clause 5;", "zh": "㈢「完成日」之意義應依第 5 條規定為定義；", "a": "cb7f122c7b9c"}, {"k": "en", "sp": "定義 (d)", "t": "(d) \"US$\" means the **lawful currency** of the United States of America.", "zh": "㈣「美金」意指美利堅合眾國之**法定貨幣**。", "a": "58f1858ddd3e"}, {"k": "tip", "t": "注意定義的三種寫法：**means**（直接給定義，如 Accounts、US$）、**shall have the meaning specified in Clause X**（指向別條，如 Completion Date）、以及引用其他已定義用語（Accounts 要看 Accounting Date）。被定義的名詞通常**依開頭英文字母順序**排列。"}, {"k": "tip", "t": "注意兩個定義**互相引用**：Accounts 要看 Accounting Date 才知道是哪一天的報表，而 Accounting Date 又要看 Accounts 才知道是哪一份報表。這種鏈狀結構很常見，審約時要把整條鏈拉出來看，才知道最後指向哪一份文件、哪一個日期。"}, {"k": "h1", "t": "定義條款的常見句型", "ic": "🧩"}, {"k": "p", "t": "means（意指）＝封閉式定義，範圍就是後面寫的那些；includes（包括）＝開放式定義，後面只是例示，範圍可能更大；means and includes＝先封閉再補充。審約時 means 與 includes 一字之差，範圍差很多。", "a": "ab12d43a016b"}, {"k": "p", "t": "其他常見解釋規則會與定義條款放在同一條（Interpretation）：words importing the singular include the plural（單數用語包含複數）、headings are for convenience only and shall not affect the interpretation（標題僅供便利，不影響解釋）、references to any statute include that statute as amended from time to time（法規之引用包括其不時修正之版本）。", "a": "236612e8a2bb"}, {"k": "h1", "t": "書中解說：定義條款的功能與讀法", "ic": "💡"}, {"k": "p", "t": "被定義之專有名詞，於合約中特別使用開頭字大寫（例如 this Facility…），以表彰這個名詞具有特殊意義，如此可避免合約條款中每處皆必須為特定名詞解釋，導致合約文字過長及複雜。", "a": "792a089b9a64"}, {"k": "p", "t": "於合約中特別標定開頭大寫之專有名詞，通常會於定義條款中，依開頭英文字母順序依序予以定義；定義條款中就特定專有名詞之解釋，也可以引用其他被定義之專有名詞（例如 Accounts 的定義，必須另外又視 Accounting Date 之定義）。", "a": "4b841e5ba8bc"}, {"k": "p", "t": "對其中使用的各種用語加以定義、確定其所指涉的範圍，可以使合約清晰化，特別是可以避免或者儘量減少合約雙方搬弄文字的機會。例如，融資合約中若提到「Facility」，經過定義係指「貸款」，那麼任何一方就沒有機會指鹿為馬的將合約中出現的「Facility」稱為「配備」、「場地」或「設施」等其他涵義。這也體現了合約的重要功能，即在合約雙方產生糾紛時，以為公正評斷雙方權利義務關係之依據。", "a": "83ca5807f55c"}, {"k": "p", "t": "定義和解釋條款的重要意義，還在於藉此機會詳細說明英文合約中涉及到的交易各方面爭議和問題。例如在融資合約中定義並解釋適用何種「會計準則」，即明確規定合約所針對交易中必須適用的會計準則，如果某一方不依約履行，則可能導致違約。", "a": "4c53505bb5f5"}, {"k": "p", "t": "定義和解釋條款的使用，還可以提高合約閱讀和理解的效率，節省合約本文的長度。但如果被定義的專有名詞太多時，有時亦會導致讀者隨時需翻閱定義條款以確定其意義，這是使用定義條款需注意之處。", "a": "b90ddae61d14"}, {"k": "tip", "t": "**第一次讀英文合約的正確順序**：先通讀一遍定義和解釋條款，概略瞭解此合約涉及的基本問題；不必強記每一個定義，接下來讀主要條款與一般條款時，凡遇到開頭字母大寫的專有名詞，再索引定義和解釋，就會事半功倍。", "a": "df40bf23c2be"}, {"k": "p", "t": "在我國法下，「定義條款」與其他合約條款具有相同的效力，因此原則上合約中對特定名詞的解釋，我國的法院會尊重當事人在合約中所為的「定義」。", "a": "5c5f3c6930ac"}, {"k": "tip", "t": "⚠ 訴訟實務上的陷阱：我國法院審理時會要求當事人（或其律師）提出外文文件之**中文譯本**以方便法官審理，此時必須注意翻譯後條款的中文文字，是否確實表達英文的文義，**以免在訴訟中反而產生對自己不利的結果**。", "a": "581d21b4a13e"}, {"k": "p", "t": "最後需注意的是，並非英文合約就一定需要定義條款，如果需定義之專有名詞不多，或使用的地方有限時，也可以直接於特定的條款之下為特別之定義，而不必另外設計定義條款。", "a": "21bcdf7e33e4"}, {"k": "voc", "v": [{"w": "unless the contract otherwise requires", "pos": "phr.", "zh": "除非合約另有約定", "syn": "unless the context otherwise requires（除依上下文另有所指外）", "trap": "這是定義條款的**安全閥**：允許在另有約定或上下文明顯不同時不套用該定義。書上印的是 contract，實務上更通用的是 context，兩者都要認得。", "tip": "", "a": "c0bd889fa519", "az": "a31838da3de5"}, {"w": "expressions", "pos": "n.", "zh": "名詞；用語", "syn": "terms／words and expressions", "tip": "the following expressions shall have the meaning…＝下列名詞應具有…之意義。", "trap": "", "a": "090a195fd3e8", "az": "76454121918b"}, {"w": "shall have the meaning set out against them", "pos": "phr.", "zh": "應具有下述所載之意義", "syn": "shall have the following meanings", "tip": "set out against them 字面是「列在它們旁邊」，源自定義採兩欄並列的排版方式。", "trap": "", "a": "1ced6a6aa0e3", "az": "0137331f002d"}, {"w": "means", "pos": "v.", "zh": "意指（封閉式定義）", "syn": "shall mean", "trap": "means 是**窮盡列舉**；若要擴張範圍必須改用 includes 或 means and includes。這一字之差是審約必查點。", "tip": "", "a": "6003ee14f48c", "az": "ea1c3723e606"}, {"w": "includes", "pos": "v.", "zh": "包括（開放式定義，例示）", "syn": "including without limitation／including but not limited to", "tip": "加上 without limitation 就是為了避免被解釋成窮盡列舉。", "trap": "", "a": "289d4aaf6c10", "az": "6b82b1d8f438"}, {"w": "audited financial statement", "pos": "n. phr.", "zh": "經審計（查核簽證）之財務報表", "syn": "audited accounts", "trap": "audited（已查核）與 management accounts（管理帳，未查核）可靠度差很多；股權買賣的價金調整常綁在 audited accounts 上。", "tip": "", "a": "6559af33aae5", "az": "1e2c06b1b5e9"}, {"w": "comprising", "pos": "prep.", "zh": "包括（由…組成）", "syn": "consisting of／made up of", "tip": "comprising 後面接的是組成部分，語氣偏封閉；若要留擴張空間用 including。", "trap": "", "a": "23b000630c97", "az": "fa7b7a220e17"}, {"w": "balance sheet", "pos": "n. phr.", "zh": "資產負債表", "syn": "statement of financial position", "tip": "表達某一時點的資產、負債與權益。", "trap": "", "a": "5a6a937e80d9", "az": "95b75becac9b"}, {"w": "profit and loss account", "pos": "n. phr.", "zh": "損益表", "syn": "income statement（美式）", "tip": "英式用 profit and loss account，美式用 income statement，內容相同。", "trap": "", "a": "6ef824c0a072", "az": "3415eeff8f46"}, {"w": "cash flow statement", "pos": "n. phr.", "zh": "現金流量表", "tip": "三大報表一起背：balance sheet、profit and loss account、cash flow statement。", "syn": "", "trap": "", "a": "a3f6d537cc28", "az": "65c962fa920d"}, {"w": "as of", "pos": "prep.", "zh": "於（截至）某日", "syn": "as at（英式）", "tip": "as of the Accounting Date＝於審計日。財務數字一定要綁定時點。", "trap": "", "a": "656a6419a6d6", "az": "de8650aea2a4"}, {"w": "with respect to", "pos": "prep. phr.", "zh": "就…而言；關於", "syn": "in respect of／in relation to", "tip": "means with respect to XYZ, the date of…＝就 XYZ 公司而言，意指…之日期。用來把定義限縮在特定主體。", "trap": "", "a": "bd6da39e5135", "az": "6ea28c578bac"}, {"w": "the financial year ended 31 December 2012", "pos": "n. phr.", "zh": "於 2012 年 12 月 31 日所終止之會計年度", "syn": "fiscal year（美式）", "trap": "ended（過去分詞）＝已結束；ending（現在分詞）＝將結束、尚未結束。一字之差時點就不同，價金調整與保證期間都會跟著錯。", "tip": "", "a": "0890f50f393a", "az": "fffeb34f5241"}, {"w": "words importing the singular include the plural", "pos": "phr.", "zh": "單數用語包含複數", "tip": "解釋條款的標準句，常與 words importing one gender include every gender 併列。", "syn": "", "trap": "", "a": "e5a78e29c718", "az": "b2163fa49d85"}, {"w": "headings are for convenience only", "pos": "phr.", "zh": "標題僅為便利之用（不影響解釋）", "syn": "headings shall not affect the construction of this Agreement", "tip": "construction 在合約裡是「解釋」的意思，不是「建造」。", "trap": "", "a": "2271a4a0ea7b", "az": "dd8ecfb9901f"}, {"w": "shall have the meaning specified in Clause 5", "pos": "phr.", "zh": "其意義應依第 5 條規定為定義", "syn": "as defined in Clause 5／has the meaning given to it in…", "tip": "定義條款的第二種寫法：不在這裡給定義，而是**指向別條**。審約時要跳過去把那一條讀完。", "trap": "", "a": "2ca33ca0d002", "az": "ef36c96f3829"}, {"w": "lawful currency", "pos": "n. phr.", "zh": "法定貨幣", "syn": "legal tender", "trap": "跨境合約一定要定義幣別（US$、HK$、NTD），否則 \"dollars\" 到底是美金還是港幣會變成爭點。", "tip": "", "a": "fff442769e90", "az": "6d6a5965c747"}, {"w": "Facility", "pos": "n.", "zh": "（融資合約中）貸款、授信額度", "trap": "書中的經典例子：Facility 一般字義是「設施、場地、配備」，但在融資合約經定義後專指「貸款」。**沒定義就會被指鹿為馬**。", "syn": "", "tip": "", "a": "b5c9ebbecda9", "az": "0353939bb5e6"}, {"w": "accounting principles / standards", "pos": "n. phr.", "zh": "會計準則", "syn": "GAAP／IFRS", "tip": "融資合約會明定適用何種會計準則，財務比率（covenants）才算得準；不依約履行可能導致違約。", "trap": "", "a": "077348338d4d", "az": "a2e5021d53b9"}, {"w": "as amended from time to time", "pos": "phr.", "zh": "及其不時之修正", "trap": "引用法規時加上這句，表示包含未來修正版本；若省略，可能被解為凍結在簽約時的版本。", "syn": "", "tip": "", "a": "58d5b67667f5", "az": "e82a5017b902"}]}]}, {"code": "3-3-1", "ch": "Chapter 參　基本條款", "sec": "三、適用優先順序及完整合約條款（Preference, Entire Agreement）", "title": "適用優先順序條款 Preference：哪一份文件說了算", "items": [{"k": "lead", "t": "一筆交易往往不只一份文件：主合約、附件（Schedule）、確認書（Confirmation）、管理協議…條款打架時誰優先？這就是「合約效力適用優先順序條款」要解決的問題。本單元讀書上的說明與一則 ISDA 式的優先順序條款範例。"}, {"k": "h1", "t": "為什麼需要優先順序條款", "ic": "📘"}, {"k": "p", "t": "交易本身常常不僅只有一份合約文件，此時，不同合約文件的條款如果有歧異時，就會有適用優先順序的問題。", "a": "4d87ebe747f4"}, {"k": "p", "t": "舉例言之，若合約文件之架構係如 ISDA 主合約系統設計為主合約、附件及確認書時，就會有主合約、附件以及確認書中的條款適用優先順序的問題，以避免不同文件之條款產生衝突或不一致（inconsistency）之情形。", "a": "90626f2ae0b9"}, {"k": "p", "t": "此外，如果該交易涉及多數的合約當事人時（例如債券的發行），則相關合約條款也可能會有適用優先順序的問題。例如於一中期債券發行計畫中，主要之信託合約可能於嗣後個別債券之發行後，繼續以其他文件加以補充，債券之主要條款也會因每一次債券的發行，而於個別發行文件中有所調整，因此有必要訂立合約效力適用優先順序條款予以規範。", "a": "c5df2e55b928"}, {"k": "tip", "t": "兩個高風險場景要立刻想到優先順序條款：**①主合約＋附件＋確認書的架構（ISDA 衍生性金融商品）**；**②多次發行、多方當事人的架構（中期債券發行計畫 MTN）**。文件越多層，越要把誰優先寫死。", "a": "5b74391f9084"}, {"k": "h1", "t": "範例・優先順序條款", "ic": "⚖️"}, {"k": "en", "sp": "附件優先", "t": "**In the event of** any **inconsistency** between this Agreement and any **Schedule hereto**, the Schedule shall prevail.", "zh": "在合約及附件的條款有**不一致**時，則附件的條款**優先適用**。", "a": "56395d77ce2d"}, {"k": "en", "sp": "管理協議§5 最優先", "t": "Sections 5 of the **Managing Agreement**, which **shall prevail** over any inconsistent or **conflicting provisions** in this Agreement notwithstanding any other provisions in this Agreement to the contrary.", "zh": "**管理協議**的第 5 條將優先於本合約中任何**不一致**或**有衝突之條款**而適用，即便本合約其他條款有相反文義。", "a": "52bb90d20947"}, {"k": "en", "sp": "其餘本約優先", "t": "Other than Section 5 of the **Managing Agreement**, in the event and **to the extent that** there shall be an **inconsistency** between the provisions of this Agreement and the provisions of the Managing Agreement, this Agreement shall prevail.", "zh": "除**管理協議**第 5 條之外，在本合約及管理協議的條款有**不一致**，於其不一致的範圍之內，本合約的條款**優先適用**。", "a": "3d027eb7e974"}, {"k": "tip", "t": "把這則條款畫成**優先順序金字塔**：① 附件（Schedule）＞ 本合約；② 管理協議第 5 條 ＞ 本合約；③ 其餘情形 本合約 ＞ 管理協議。三句話建立了完整的三層次序，沒有留下空隙——這就是好的優先順序條款。"}, {"k": "h1", "t": "書中解說", "ic": "💡"}, {"k": "p", "t": "在這個合約裡，除了主合約之外，尚有一些附件，另外當事人間也簽訂了一個管理協議。在這個條款之下，則附件的條款具有最優先性，除管理協議的第 5 條之外，主合約的條款將優先適用管理協議。", "a": "9fa55c7a9633"}, {"k": "p", "t": "合約效力適用優先順序條款的效力，於我國司法實務上會受到尊重及承認。意即，當事人若約定一部分的合約條款優先於其他部分條款的適用，我國法院會予以尊重，而依當事人的約定，決定條款適用的順序及優先性。", "a": "bc68ed0eab29"}, {"k": "voc", "v": [{"w": "inconsistency", "pos": "n.", "zh": "不一致；歧異", "syn": "conflict／discrepancy", "tip": "條款標題常寫 Inconsistency／Order of Precedence／Conflict of Terms，看到就知道是優先順序條款。", "trap": "", "a": "b1a44738bac6", "az": "62009e722c96"}, {"w": "in the event of", "pos": "prep. phr.", "zh": "於…情形發生時", "syn": "if／in case of／in the event that", "tip": "in the event of＋名詞；in the event that＋子句。合約最常見的假設語句。", "trap": "", "a": "2b6d3f888e23", "az": "4504d6f1785f"}, {"w": "shall prevail", "pos": "v. phr.", "zh": "優先適用；以…為準", "syn": "shall govern／shall take precedence over", "trap": "prevail 在這裡不是「獲勝」而是「優先適用」。基準語言條款的 \"this English version shall govern\" 是同一個用法。", "tip": "", "a": "7067b2f085f6", "az": "a74f0c22f265"}, {"w": "Schedule hereto", "pos": "n. phr.", "zh": "本合約之附件", "syn": "Annex／Appendix／Exhibit／Attachment", "trap": "附件是不是合約的一部分、能不能優先於本文，都要寫清楚，否則爭議時無解。", "tip": "", "a": "1841164549f3", "az": "b7e7ccd89077"}, {"w": "notwithstanding any other provisions to the contrary", "pos": "phr.", "zh": "即便（本合約）其他條款有相反文義", "syn": "notwithstanding anything to the contrary herein", "trap": "這是合約裡最強的**凌駕句**：它會蓋過其他條款。看到 notwithstanding 就要立刻找出它蓋掉了什麼。", "tip": "", "a": "c560382080e0", "az": "2ffefc1da9f3"}, {"w": "conflicting provisions", "pos": "n. phr.", "zh": "有衝突之條款", "syn": "inconsistent provisions", "tip": "inconsistent（不一致）比 conflicting（衝突）範圍更寬，兩個字常並列使用以求周延。", "trap": "", "a": "da1abdbc562d", "az": "346b3bff21e4"}, {"w": "to the extent that", "pos": "phr.", "zh": "於…之範圍內", "syn": "insofar as", "trap": "**限縮語**。\"to the extent that there shall be an inconsistency\" 表示只在衝突的那一小塊優先，其餘條款仍各自有效，不是整份文件被取代。", "tip": "", "a": "3a4d8780dd6f", "az": "b10abeeab849"}, {"w": "Managing Agreement", "pos": "n. phr.", "zh": "管理協議", "tip": "債券發行中由主辦機構與發行人簽訂的協議；本例把它的第 5 條拉到最優先。", "syn": "", "trap": "", "a": "a882f256bb8a", "az": "611ab52458b0"}, {"w": "Master Agreement", "pos": "n. phr.", "zh": "主合約", "syn": "ISDA Master Agreement", "tip": "衍生性金融商品的標準架構：Master Agreement ＋ Schedule ＋ Confirmation，三層文件就是靠優先順序條款串起來。", "trap": "", "a": "c53d8ad4d7c2", "az": "9a652b6262b1"}, {"w": "Confirmation", "pos": "n.", "zh": "確認書", "tip": "ISDA 架構中記載個別交易條件的文件，通常約定其條款優先於主合約。", "syn": "", "trap": "", "a": "9498efa00547", "az": "a68fe329d297"}, {"w": "medium term note programme", "pos": "n. phr.", "zh": "中期債券發行計畫", "syn": "MTN programme", "tip": "一次建立計畫、多次發行；每次發行的個別文件會調整主要條款，所以必須有優先順序條款。", "trap": "", "a": "30ca47801819", "az": "8fa9b779edc6"}, {"w": "trust deed", "pos": "n. phr.", "zh": "信託合約（契約）", "tip": "債券發行中規範受託人與債券持有人關係的主要文件。", "syn": "", "trap": "", "a": "76dd7b7e6a3f", "az": "ab5af64abf79"}, {"w": "supplement", "pos": "v./n.", "zh": "補充（文件）", "syn": "amend and restate", "tip": "主要文件在後續發行時「繼續以其他文件加以補充」，層層疊加正是衝突的來源。", "trap": "", "a": "dbd31466fe96", "az": "01be7e8d17f2"}]}]}, {"code": "3-3-2", "ch": "Chapter 參　基本條款", "sec": "三、適用優先順序及完整合約條款（Preference, Entire Agreement）", "title": "完整合約條款 Entire Agreement：之前談的全部一筆勾銷", "items": [{"k": "lead", "t": "談判期間來來回回的 email、意向書（LOI）、備忘錄（MOU）、口頭承諾——簽約之後還算不算數？完整合約條款就是用一句話把它們全部取代掉。這是英文合約最常見、也最容易被當成樣板而忽略的一般條款。"}, {"k": "h1", "t": "完整合約條款的功能", "ic": "📘"}, {"k": "p", "t": "所謂完整合約條款（entire agreement clause or whole agreement clause），係在確認和強調一份合約中涉及和包含的所有部分，為同一份完整的合約。", "a": "e8259864498c"}, {"k": "p", "t": "特別是對於包含諸多附件或者附表的合約來說，附件或附表都是與該合約中其他條款歸屬於同一份合約，其生效、終止、失效和執行都必須根據同一份合約中約定的內容為適用。", "a": "751874455c8a"}, {"k": "h1", "t": "範例・完整合約條款", "ic": "📄"}, {"k": "en", "sp": "完整合約", "t": "This Contract **contains the entire agreement** of the parties and supersedes all **prior agreements**, arrangements and letters of intent between the parties, **no matter they are made in writing and orally**.", "zh": "本合約係包含當事人間所有的完整合約，且取代先前當事人間以書面或口頭所達成的任何協議、安排或**意向書**等。", "a": "5d9d571bd84e"}, {"k": "tip", "t": "條款的兩個動作：**contains the entire agreement（本約就是全部）** ＋ **supersedes all prior…（先前的全部取代掉）**，而且明說 in writing and orally（書面與口頭都算）。少寫任何一半，效果都會打折。"}, {"k": "h1", "t": "書中解說", "ic": "💡"}, {"k": "p", "t": "完整合約條款是在說明，這份合約是代表當事人間所有就此筆交易的完整合約，而且取代當事人間先前無論是書面或口頭達成的其他協議、承諾、安排或意向書等。", "a": "8b0e109f8c50"}, {"k": "p", "t": "目的就在於確保當事人的權利義務關係，完全依所簽訂最終之合約文件所記載的內容為準，先前其他口頭或書面所達成的各種協議，自本合約簽訂之後即被取代，以避免將來產生法律糾紛。", "a": "7266e90f9758"}, {"k": "p", "t": "在我國法下，完整合約條款會發生當事人所約定的效果，因此在我國法下，一旦合約有完整合約條款，則先前以口頭或書面之所有的任何協議，除非完整合約條款中有所保留，否則應皆不再生任何的效力。", "a": "d1c5d029cb2f"}, {"k": "tip", "t": "⚠ 書中的重要但書：完整合約條款**並不會影響**合約當事人依我國民法得行使之**可得撤銷合約**（例如因詐欺或脅迫而撤銷）的權利。也就是說，它可以掃掉先前的「協議」，但掃不掉對方詐欺你這件事。", "a": "0a2eda710ec1"}, {"k": "voc", "v": [{"w": "entire agreement clause", "pos": "n. phr.", "zh": "完整合約條款", "syn": "whole agreement clause／integration clause（美式）", "tip": "美式合約常以 Integration 或 Merger Clause 為標題，意思相同。", "trap": "", "a": "ff9c5ac5eda9", "az": "f7b42d500ff3"}, {"w": "contains the entire agreement", "pos": "v. phr.", "zh": "包含（當事人間）所有的完整合約", "syn": "constitutes the entire agreement", "tip": "標準句型：This Agreement constitutes the entire agreement between the parties with respect to the subject matter hereof.", "trap": "", "a": "ac60a6b7b791", "az": "e5b2a6d34ace"}, {"w": "supersede", "pos": "v.", "zh": "取代；優先於（而使先前者失效）", "syn": "replace／override", "trap": "supersede 是**使先前文件失效**；prevail 只是「在衝突時優先適用」，先前文件仍存在。兩個字效果差很多。", "tip": "", "a": "ab4c8b585809", "az": "5a23d3f43879"}, {"w": "prior agreements", "pos": "n. phr.", "zh": "先前之協議", "syn": "previous agreements／antecedent agreements", "tip": "常與 arrangements、understandings、negotiations、representations 並列，寫越多掃得越乾淨。", "trap": "", "a": "94fb5b269b6b", "az": "cb30fbc52248"}, {"w": "arrangements", "pos": "n.", "zh": "安排；默契", "tip": "比 agreement 更鬆散的合意也要一併掃掉，所以要寫進去。", "syn": "", "trap": "", "a": "2f5381c528c8", "az": "7e9e4abef3c9"}, {"w": "letter of intent", "pos": "n. phr.", "zh": "意向書", "syn": "LOI／MOU（memorandum of understanding）／term sheet", "trap": "意向書中常有少數**有拘束力的條款**（保密、排他協商、費用分擔）。完整合約條款若沒把它們排除（carve out），可能連這些也一併失效。", "tip": "", "a": "fdb74613e8a2", "az": "84ab98488439"}, {"w": "no matter they are made in writing and orally", "pos": "phr.", "zh": "無論係以書面或口頭所達成", "syn": "whether written or oral", "tip": "把口頭承諾也納入取代範圍，是本條款最實用的一半。", "trap": "", "a": "2f3a5c1421f7", "az": "73f97ef53fda"}, {"w": "with respect to the subject matter hereof", "pos": "phr.", "zh": "就本合約標的事項而言", "trap": "實務上非常重要的**限縮語**：只取代「關於這筆交易」的先前協議，不會誤掃掉雙方其他不相干的合約（例如既有的保密協議、代理合約）。", "syn": "", "tip": "", "a": "9aa45a491736", "az": "9a04336abae9"}, {"w": "save as expressly provided herein", "pos": "phr.", "zh": "除本合約另有明文規定外", "syn": "except as otherwise provided herein", "tip": "用來做 carve out（保留條款），把要留下來的先前文件挑出來。", "trap": "", "a": "f25e274a7b9d", "az": "6d80a8d71ee1"}, {"w": "rescind / set aside", "pos": "v.", "zh": "撤銷（合約）", "syn": "revoke／avoid", "trap": "書中特別點出：完整合約條款**不影響**因詐欺或脅迫而依民法撤銷合約的權利。它掃得掉「協議」，掃不掉「詐欺」。", "tip": "", "a": "413f75e69f0c", "az": "81db5f240f47"}, {"w": "non-reliance", "pos": "n.", "zh": "不信賴（聲明）", "tip": "進階寫法：加一句雙方聲明未信賴本約以外的任何陳述（no reliance on any representation not set out herein），用來阻斷 misrepresentation 的主張。", "syn": "", "trap": "", "a": "dfd9df44fb68", "az": "4fbef31b0840"}]}]}, {"code": "3-4-1", "ch": "Chapter 參　基本條款", "sec": "四、合約效力及內容範圍（Contract Effectiveness）", "title": "約因與價金 Consideration & Purchase Price：英美法的對價", "items": [{"k": "lead", "t": "約因（consideration）是英美合約法特有的概念，也是我國法所沒有的。它決定合約能不能請求法院強制執行。本單元讀書上的概念說明，再看三種把約因寫進合約的方式：①約因作為價金 ②約因之陳述 ③直接約定價金。"}, {"k": "h1", "t": "本節總說：影響合約效力的因素", "ic": "📘"}, {"k": "p", "t": "一份合約之中，除就特定交易所設計之主要交易條款之外，最重要之處即為確定這一份合約在法律上係有效可以被執行的。影響合約效力的因素有很多，有可能因為詐欺、錯誤、脅迫等外部因素被撤銷，有可能因為合約沒有經授權人士簽名而不生效力。", "a": "ebde41069f2f"}, {"k": "p", "t": "除了這些情形之外，合約當事人也可以於合約中就合約生效或失效的條件、合約一部失效時的效果、合約的完整性、約因或對價，以及合約的期間等予以特別約定。本節介紹若干影響合約效力及內容範圍的條款。", "a": "1171ccaa3e85"}, {"k": "h1", "t": "約因（Consideration）是什麼", "ic": "💡"}, {"k": "p", "t": "約因（consideration）是英美合約法中特別的法律概念，特別是對合約本身是否可以請求法院強制執行時，扮演關鍵性的角色。某些合約中，直接使用認購價金條款，將其具體化和明確化，以便確認合約雙方的認購價金。", "a": "f08e40a99bdb"}, {"k": "p", "t": "約因的概念類似於中文的「對價」的概念，意即當事人一方所為的承諾（promise），必須要在另一方當事人有提供相對的承諾或為若干行為，使得一方當事人獲有利益，或他方當事人權利受到有損害，權利不行使或行為之容忍。", "a": "de6cf826687b"}, {"k": "p", "t": "約因需經過「交易磋商，bargain for」之過程及相對人「法律上權益受損，legal detriment」之要素。在這個前提下，英美法認為，此時當事人間之合意，係經過慎思熟慮之過程而達成的，所以法院對此可以強制執行；約因的概念主要在排除贈與合約，此有其歷史背景。類似的觀念並不存在於大陸法系的國家（包括我國法）之中。", "a": "a965674b23c1"}, {"k": "p", "t": "但是，英美法中約因的概念，已轉化為合約條款之中，呈現的方式有二種：以單純陳述的方式表明約因，或訂定單獨的約因條款。以下將分別介紹。", "a": "3b89fc480eb1"}, {"k": "tip", "t": "約因的兩個要素：**bargain for（交易磋商）＋ legal detriment（法律上權益受損）**。所以單純的贈與承諾沒有約因、不可強制執行——這正是這個制度的歷史目的。", "a": "b64e61d49d75"}, {"k": "h1", "t": "例一・約因作為價金", "ic": "💰"}, {"k": "en", "sp": "第1條 定義", "t": "Clause 1 — \"**Consideration**\" means the consideration for the Sale Shares following adjustment as set out in Clause 4.", "zh": "第 1 條　「約因」，意指銷售股份之對價，且依第 4 條規定調整。", "a": "43ebbb51f9f7"}, {"k": "en", "sp": "第4.1條", "t": "4.1 **Subject to adjustment pursuant to** clause 4.2 below, the **Consideration** for the sale and purchase of Sale Shares shall be NTD 400,000,000.", "zh": "4.1　依下列第 4.2 條調整，買賣股份之對價為新臺幣四億元。", "a": "2f4e3ad4da93"}, {"k": "en", "sp": "第4.3條", "t": "4.3 The final Consideration shall be **the aggregate of the amounts** under Clauses 4.2 (a), 4.2 (b) and any profits or losses between 1 March 2012 and Completion Date as reflected in XXX's **management accounts** **as at Completion Date**.", "zh": "4.3　最後的約因為依第 4.2(a) 及 4.2(b) 條計算金額，及 2012 年 3 月 1 日至完成日間之任何**利益或損失**（反應於 XXX **於完成日**的**經營帳戶**）之總合。", "a": "36be274255ae"}, {"k": "p", "t": "於上例的合約中明確地定義，所謂「約因」（consideration）指的是依合約第 4 條所定義買賣股份之價金。而依第 4 條的規定，原則上價金是新臺幣四億元，這是買方的給付義務，而相對地，賣方所提供的約因（即其義務）則依第 4.3 條以後的記載而定，因此，買方與賣方互相所提供的約因，在本合約第 4 條予以規定。"}, {"k": "tip", "t": "注意 **Subject to adjustment pursuant to clause 4.2**：價金四億元只是起點，真正的價金要等交割日的管理帳目（management accounts）算完才確定。這就是股權交易的 **price adjustment（價金調整）** 機制。"}, {"k": "h1", "t": "例二・約因之陳述", "ic": "📝"}, {"k": "p", "t": "除了以約因條款特別明訂雙方互負的義務之外，一般常見提及「約因」的方式是以一般陳述性的語句呈現，例如："}, {"k": "en", "sp": "寫法一", "t": "Now, **in consideration of the mutual covenants herein contained**, the parties hereby agree as follows:", "zh": "是故，**為考量當事人雙方於本合約所為之相互承諾**，當事人據此同意下列事項：", "a": "7f3f4724bb08"}, {"k": "en", "sp": "寫法二", "t": "Now therefore, in **consideration** of the mutual agreements, representations, warranties and subject to the conditions contained herein, the parties hereto hereby agree as follows:", "zh": "是故，為考量當事人雙方已於本合約為後述之共同協議、陳述、保證，且適用本合約下列之條件，當事人據此依本合約同意下列事項：", "a": "0a44852c0e0a"}, {"k": "p", "t": "如果用這種方式呈現，亦即代表當事人雙方互相所提供的約因，就是依本合約所記載的相互的權利與義務、陳述、保證及條件等。"}, {"k": "tip", "t": "💡 **給我國讀者最實用的一句**：在我國法下並沒有所謂的「約因」的概念，因此英文合約中的「約因條款」，於合約的準據法為我國法時，可將之視為**合約的價金或主要給付義務的條款**，而不必執著於英美法下「約因」的概念，這也符合「約因」概念的原意。"}, {"k": "h1", "t": "例三・價金約定", "ic": "🚢"}, {"k": "p", "t": "在合約中，當事人自然也可以直接約定交易的價金數額，例如："}, {"k": "en", "sp": "價金條款", "t": "The **total purchase price** to be paid by Buyer to Seller for the Equipment **described herein** shall be US$250,000 FOB Liverpool.", "zh": "買方就標的設備所應給付予賣方之價金，為美金二十五萬元整，於利物浦港以 FOB 報價。", "a": "ca01f74f39b0"}, {"k": "p", "t": "這個條款之中，直接約定了買賣標的價金為美金二十五萬元整，報價的內容是「FOB Liverpool」，所以賣方的報價是以 FOB 的方式至利物浦港上船之報價。「FOB」是國貿條款，賣方的報價是由其負擔至貨物上船之一刻為止，當事人自然也可以約定適用其他的國貿條款（例如 CIF 或 CFR 等），不過賣方報價的內容會視不同條款而有所差異。"}, {"k": "tip", "t": "報價一定要連**國貿條規（Incoterms）**一起寫：FOB（Free On Board 船上交貨，賣方負擔到貨物上船為止）／CFR（含運費）／CIF（含運費與保險）。只寫 US$250,000 而沒寫條件，運費、保險、風險移轉通通是爭點。"}, {"k": "voc", "v": [{"w": "consideration", "pos": "n.", "zh": "約因；對價", "syn": "價金（purchase price）／主要給付義務", "trap": "**不是「考慮」**。英美法下沒有 consideration 合約可能不能強制執行；我國法無此概念，可直接理解為價金或主要給付義務。", "tip": "", "a": "0d33cf2ff7f4", "az": "38b5227d3730"}, {"w": "bargain for", "pos": "v. phr.", "zh": "交易磋商", "tip": "約因的第一個要素：承諾必須是「換來的」，不是單方給的。", "syn": "", "trap": "", "a": "c465aa6622a1", "az": "72a2a7e6f10e"}, {"w": "legal detriment", "pos": "n. phr.", "zh": "法律上權益受損", "tip": "約因的第二個要素：他方權利受損、不行使權利或容忍某行為，也算對價。", "syn": "", "trap": "", "a": "61145892a079", "az": "72636658ae7e"}, {"w": "promise", "pos": "n./v.", "zh": "承諾", "syn": "covenant／undertaking", "tip": "一方的 promise 要有對方的 promise 或行為來交換，才構成 consideration。", "trap": "", "a": "23d1ad604e04", "az": "ec59c9cdf5a4"}, {"w": "gift / gratuitous promise", "pos": "n. phr.", "zh": "贈與／無償承諾", "trap": "約因制度的歷史目的就是**排除贈與合約**的強制執行。英美法下單純贈與承諾不可強制執行（除非以 deed 作成）。", "syn": "", "tip": "", "a": "cbdaaaeb8f9a", "az": "9911d4ae7c32"}, {"w": "subject to adjustment pursuant to", "pos": "phr.", "zh": "依…規定調整", "syn": "subject to the adjustments set out in", "tip": "股權交易的價金調整（price adjustment）機制起手式：先訂基準價，再依交割日帳目加減。", "trap": "", "a": "76c382d41fc9", "az": "4cb5815b9db2"}, {"w": "the aggregate of the amounts", "pos": "n. phr.", "zh": "…金額之總合", "syn": "the sum of／the total of", "tip": "aggregate 在金融與併購合約中極高頻，意為合計、總額。", "trap": "", "a": "f3d1e5c2e67d", "az": "414f419ab3db"}, {"w": "management accounts", "pos": "n. phr.", "zh": "經營帳戶；管理帳目", "syn": "internal accounts", "trap": "management accounts 是**未經查核**的內部帳，和 audited accounts（經查核財報）可信度不同。價金若綁在管理帳上，要另外約定編製基礎與爭議解決（expert determination）。", "tip": "", "a": "c34fa93f6948", "az": "00a625db00b2"}, {"w": "as at Completion Date", "pos": "prep. phr.", "zh": "於完成日（當時）", "syn": "as of the Completion Date", "tip": "as at／as of＋時點，財務數字一定要綁時點。", "trap": "", "a": "dd909fc343ab", "az": "6743be1e537d"}, {"w": "profits or losses", "pos": "n. phr.", "zh": "利益或損失", "tip": "本例把簽約日到交割日之間的損益也算進價金，叫做 locked box 的相對概念（completion accounts 機制）。", "syn": "", "trap": "", "a": "491bcda362ea", "az": "2ea59d3823e3"}, {"w": "in consideration of the mutual covenants herein contained", "pos": "phr.", "zh": "為考量當事人雙方於本合約所為之相互承諾", "tip": "最標準的約因陳述句，背起來。", "syn": "", "trap": "", "a": "ec7dc5255eec", "az": "5447a2bb7a6e"}, {"w": "total purchase price", "pos": "n. phr.", "zh": "總價金", "syn": "contract price／contract sum", "tip": "貨物買賣直接寫 total purchase price 最清楚。", "trap": "", "a": "4a230f751ddd", "az": "3934bb1971ea"}, {"w": "FOB (Free On Board)", "pos": "n. phr.", "zh": "船上交貨（國貿條規）", "syn": "CFR（含運費）／CIF（含運費保險）／EXW（工廠交貨）", "trap": "FOB 的賣方只負擔到**貨物上船之一刻**；越往 CIF 走賣方責任越重、報價越高。報價沒寫 Incoterm 等於沒報完。", "tip": "", "a": "12319f76c2a6", "az": "8f62ad50cfac"}, {"w": "Incoterms", "pos": "n.", "zh": "國貿條規", "tip": "國際商會制定的貿易條件，記得寫版本年份（如 Incoterms 2020），否則適用哪一版也會變成爭點。", "syn": "", "trap": "", "a": "2451cce04434", "az": "0fc8fc263a46"}, {"w": "described herein", "pos": "phr.", "zh": "本合約所述之", "syn": "set out herein／specified herein", "tip": "the Equipment described herein＝本合約所述之標的設備。", "trap": "", "a": "2552b31c6d4a", "az": "fbe0c8a4e422"}]}]}, {"code": "3-4-2", "ch": "Chapter 參　基本條款", "sec": "四、合約效力及內容範圍（Contract Effectiveness）", "title": "停止條件 Condition Precedent：條件成就，合約才生效", "items": [{"k": "lead", "t": "停止條件（又稱先決條件）規定「要先發生什麼，合約或某項權利義務才生效」。本單元先把英美法下 condition 的三種意義分清楚（這是最容易誤讀的地方），再讀一則取得主管機關核准為停止條件的範例，最後對照我國民法第 99 條。"}, {"k": "h1", "t": "停止條件是什麼", "ic": "📘"}, {"k": "p", "t": "另一種常見的條款，就是停止條件（condition precedent），或可稱先決條件。英文合約的標的是交易，合約雙方得預設交易生效需要出現的前提條件，也就是停止條件。在合約中，雙方通過停止條件條款，約定只有在此條件發生後，合約中的某一項權利義務關係，乃至合約本身才可以生效。", "a": "e8ff2569f7f6"}, {"k": "p", "t": "停止條件條款和表述條款（representations）之間的區別，在於停止條件條款針對的是尚未出現的但應當出現的某些事實或事件，而表述條款是表述業已存在的事實或事件。", "a": "b179e58d7e5e"}, {"k": "p", "t": "常見的停止條件條款，例如涉及政府管制貨品貿易的進出口業務中，獲得足夠的配額（quota）或者必須持有許可證（license）等，都是貿易進行的停止條件。在此等情形下，如果沒有配額或許可證，貿易就變成了非法的走私，交易本身不會受合約以及法律的保護，合約關係也就無從談起。", "a": "54282f5af608"}, {"k": "tip", "t": "**一句話分清楚**：停止條件＝**還沒發生但應該發生**的事（未來）；表述（representation）＝**已經存在**的事實（過去／現在）。考點與審約的第一個分辨點。", "a": "6314c19997d6"}, {"k": "h1", "t": "⚠ condition 一詞的三種意義", "ic": "🔀"}, {"k": "p", "t": "所謂的「條件」（condition）一詞，在英美合約法下至少有三種意義。其一，「condition」一詞可以單純指的是合約條款，最常見的方式就是使用「terms and conditions」，於這種情形之下，「condition」一詞並沒有非使合約生效或失效的效果，而單純指的是「合約條款」而已。", "a": "61eda71f4a68"}, {"k": "p", "t": "其次，「condition」一詞可以指的是「重要的」合約條款，且因為其重要性，所以在違反時於英美法下會產生使未違約的一方享有終止合約（terminate）的權利，此時，「condition」一詞也與合約的生效或失效無關，而單純指的是「重要條款」而已，其相對詞是「warranty」。", "a": "c23202f1a82e"}, {"k": "p", "t": "其三，所謂的「condition」，可以指的是使合約生效或失效的條件，也就是此處所要介紹的停止條件（通常以「condition precedent」表示）以及下節中的解除條件（condition subsequent）。", "a": "ba012c7edb66"}, {"k": "tip", "t": "英文合約的讀者在閱讀合約時，要仔細判斷「condition」一詞所代表的意義，因為在不同的狀況下其意義會有所不同，**不是所有的地方使用「condition」一詞都代表停止條件**。", "a": "608d91fea169"}, {"k": "h1", "t": "範例・停止條件條款", "ic": "🏛️"}, {"k": "en", "sp": "標題", "t": "Condition Precedent", "zh": "停止條件", "a": "b4125f4a93ca"}, {"k": "en", "sp": "前提條件", "t": "The obligation of the parties under this Contract **is subject to** Purchaser obtaining the **Approval** from **government authority**.", "zh": "當事人於本合約下產生義務的前提條件，係買方必須從**主管機關**取得核准。", "a": "39d28f1d3a68"}, {"k": "en", "sp": "未成就之效果", "t": "Vendor may terminate this Agreement **at its sole discretion** if Purchaser **fails to obtain** the Approval on or prior to [date] (\"**Long Stop Date**\").", "zh": "假若買方未能於指定期日前取得核准，賣方可以**依其單獨**權限終止本合約。", "a": "05af320e02eb"}, {"k": "en", "sp": "得合意延長", "t": "Parties may agree to extend the **Long Stop Date** for such period of time and **subject to such terms as the parties may mutually agree** (\"**New Completion Date**\").", "zh": "但當事人可以合意同意延長指定的期限（即**新完成日**）。", "a": "7fabdb9e1502"}, {"k": "p", "t": "依照這個條款，本合約下的義務是否有效，其前提條件為買方在指定的日期前需取得主管機關的核准或同意，相對地，若未能取得主管機關的核准或同意時，則該停止條件並未成就，合約也因此不生效力，因此雙方自然不需要依合約互負給付義務。"}, {"k": "tip", "t": "**Long Stop Date（最後期限日）** 是跨境交易的靈魂零件：條件不是無限期等下去，到了這個日子還沒成就，一方就可以走人。審約時務必確認三件事——誰負責取得核准、要盡到什麼程度的努力（best / reasonable endeavours）、以及 Long Stop Date 到了的後果。"}, {"k": "h1", "t": "我國法對照：民法第 99 條", "ic": "⚖️"}, {"k": "p", "t": "在我國民法的架構之下，合約的當事人可以自己約定各種條件。依民法第 99 條的規定：「附停止條件之法律行為，於條件成就時，發生效力。」「附解除條件之法律行為，於條件成就時，失其效力。」「依當事人之特約，使條件成就之效果，不於條件成就之時發生者，依其特約。」", "a": "93a48c4ea2af"}, {"k": "p", "t": "因此，英文合約中的「condition precedent」以及前面所舉範例，皆符合我國民法第 99 條的規定，條件成立或不成立的法律效果。", "a": "c1028be7d8df"}, {"k": "voc", "v": [{"w": "condition precedent", "pos": "n. phr.", "zh": "停止條件；先決條件", "syn": "CP／precondition", "trap": "簡稱 CP。注意與 condition subsequent（解除條件）效果相反。", "tip": "", "a": "d436087d433a", "az": "03677529ebd8"}, {"w": "is subject to", "pos": "v. phr.", "zh": "以…為前提條件；受…拘束", "syn": "is conditional upon／is contingent on", "tip": "合約最高頻的句型之一，看到就要問「被什麼綁住了」。", "trap": "", "a": "6fe43cd5eba1", "az": "91eec054e89f"}, {"w": "terms and conditions", "pos": "n. phr.", "zh": "合約條款", "trap": "這裡的 condition **只是「條款」**，與合約生效失效無關。這是 condition 的第一種意義。", "syn": "", "tip": "", "a": "baa8c19d1395", "az": "e52c0eae1af4"}, {"w": "condition (重要條款)", "pos": "n.", "zh": "重要條款", "syn": "相對詞 warranty（非重要條款）", "trap": "condition 的第二種意義：違反**重要條款**時，未違約一方取得終止合約的權利；違反 warranty 則只能請求損害賠償。", "tip": "", "a": "bf2ea91a208f", "az": "87a5165a4f6d"}, {"w": "Approval", "pos": "n.", "zh": "（主管機關之）核准", "syn": "consent／permit／clearance", "tip": "大寫 Approval 代表是定義過的用語，要回去查它指哪一個機關的哪一種核准。", "trap": "", "a": "9071dcd96115", "az": "02a62150e4b2"}, {"w": "government authority", "pos": "n. phr.", "zh": "主管機關", "syn": "competent authority／regulator", "tip": "跨境併購常見 CP：投審會／公平會／外資審查／反壟斷申報。", "trap": "", "a": "e3546333eea4", "az": "f90ad5f5b631"}, {"w": "quota", "pos": "n.", "zh": "配額", "tip": "政府管制貨品貿易的經典停止條件，沒配額交易就變成走私。", "syn": "", "trap": "", "a": "91bc761cb084", "az": "1af5a6108425"}, {"w": "license", "pos": "n.", "zh": "許可證", "syn": "permit／licence（英式拼法）", "tip": "與 quota 並列為書中舉的兩個典型停止條件。", "trap": "", "a": "ca9feb8114cb", "az": "003ac4d65bb3"}, {"w": "at its sole discretion", "pos": "phr.", "zh": "依其單獨（絕對）權限", "syn": "in its absolute discretion", "trap": "**單方說了算**的措辭。拿到對方草稿看到這句，要評估是否改為 acting reasonably（合理行使）。", "tip": "", "a": "4a53fb20daa7", "az": "d97f85baeb45"}, {"w": "fails to obtain", "pos": "v. phr.", "zh": "未能取得", "syn": "does not obtain", "tip": "fail to＋原形＝未能…，合約中表示義務未履行的標準寫法。", "trap": "", "a": "c38d9eb515df", "az": "45311cea3d53"}, {"w": "on or prior to", "pos": "prep. phr.", "zh": "於…當日或之前", "syn": "on or before", "trap": "合約談日期一定要寫清楚含不含當日。on or prior to＝含當日。", "tip": "", "a": "cc4836f345fc", "az": "12a3d45d4812"}, {"w": "Long Stop Date", "pos": "n. phr.", "zh": "最後期限日", "syn": "Longstop Date／Outside Date（美式）／Drop Dead Date", "tip": "條件最晚要成就的日子；到期未成就，一方得終止。跨境交易必備。", "trap": "", "a": "d569173c4bcc", "az": "17606777e652"}, {"w": "New Completion Date", "pos": "n. phr.", "zh": "新完成日", "tip": "雙方合意延長 Long Stop Date 後的新交割日。", "syn": "", "trap": "", "a": "2df0034dd4d2", "az": "f99504a32c49"}, {"w": "subject to such terms as the parties may mutually agree", "pos": "phr.", "zh": "依當事人所得合意之條件", "tip": "保留彈性的寫法，但也代表延期要另行談，沒有自動延長。", "syn": "", "trap": "", "a": "88a5bdc7e402", "az": "39159efe2e63"}, {"w": "best endeavours / reasonable endeavours", "pos": "n. phr.", "zh": "最大努力／合理努力", "trap": "停止條件一定要配一條努力義務：best endeavours（最大努力，責任最重）＞ all reasonable endeavours ＞ reasonable endeavours。英式用 endeavours，美式用 efforts。", "syn": "", "tip": "", "a": "4809c1e0bbbc", "az": "e86af6e8a636"}]}]}, {"code": "3-4-3", "ch": "Chapter 參　基本條款", "sec": "四、合約效力及內容範圍（Contract Effectiveness）", "title": "解除條件 Condition Subsequent：條件成就，合約失效", "items": [{"k": "lead", "t": "解除條件的效果和停止條件剛好相反：約定的事件一發生，合約或合約所訂的義務就失其效力。本單元讀一則以「貸款人未如期取得董事會決議證書則合約自動失效」為解除條件的範例，並對照我國民法第 99 條第 2 項。"}, {"k": "h1", "t": "解除條件是什麼", "ic": "📘"}, {"k": "p", "t": "「解除條件」（condition subsequent）係指雙方當事人約定的事件發生時，則合約或合約所訂的義務將失其效力，即當事人可以不再繼續依合約履行，因此，解除條件的效果剛好和停止條件相反。", "a": "8ce0972cdbf8"}, {"k": "tip", "t": "一句話記住：**停止條件＝條件成就才生效（開關打開）；解除條件＝條件成就就失效（開關關掉）**。", "a": "0f920f724361"}, {"k": "h1", "t": "範例・解除條件條款", "ic": "📄"}, {"k": "en", "sp": "自動失效", "t": "This Agreement shall **become automatically void** and **of no force and effect** if on or prior to June 13, 2012 Lender shall not have received a certificate from **the Secretary** or K Corp. certifying (as applicable) that", "zh": "假若貸款人無法於 2012 年 6 月 13 日前自 K 公司取得下列證書，則本合約將**自動失效**，且**不再生任何效力**：", "a": "6b8a531252eb"}, {"k": "en", "sp": "(a) 決議真正", "t": "(a) attached to each such certificate is a **true, complete and correct copy** of the **resolutions of the Board of Directors** of K Corp. authorizing among other things the **execution, delivery and performance** of this Agreement, and", "zh": "(a) 於本證書附有 K 公司之董事會真實、完整且正確的**董事會決議**，以授權執行、交付及履行本合約；且", "a": "3907e55a83f1"}, {"k": "en", "sp": "(b) 決議未變", "t": "(b) such resolutions have not been **amended, modified, revoked or rescinded** **since the dates on which they were adopted**.", "zh": "(b) 此**董事會決議****自決議**日起至今尚未經**修訂、更改、撤銷或撤回**。", "a": "a922d509339f"}, {"k": "p", "t": "從上述條款可知，此合約的效力，是建立在 K 公司的有效的董事會決議授權，與前面的停止條件不同的是，此條件並不是設定為合約生效的前提要件，而是設定為貸款人必須在指定的期限前提出證書證明有效董事會決議的存在，否則這個合約就會自動失效。"}, {"k": "tip", "t": "同一件事（董事會決議授權）可以寫成**停止條件**（取得才生效）也可以寫成**解除條件**（沒取得就失效）。差別在於**過渡期間合約有沒有效**——解除條件下合約先生效，拿不到才倒回去；停止條件下合約根本還沒生效。談判時這一點值得爭。"}, {"k": "h1", "t": "我國法對照：民法第 99 條第 2 項", "ic": "⚖️"}, {"k": "p", "t": "在我國法下，依民法第 99 條第 2 項之規定：「附解除條件之法律行為，於條件成就時，失其效力。」故上例的條款，符合民法上開條文的規定。", "a": "45f539dc1be3"}, {"k": "voc", "v": [{"w": "condition subsequent", "pos": "n. phr.", "zh": "解除條件", "syn": "resolutive condition", "trap": "與 condition precedent 效果**相反**：前者成就使合約失效，後者成就才生效。", "tip": "", "a": "9a038c5cd8a8", "az": "788457261b54"}, {"w": "become automatically void", "pos": "v. phr.", "zh": "自動失效", "syn": "automatically terminate／lapse", "trap": "**自動**＝不必再通知、不必再主張。對想保留彈性的一方很危險，通常會改成「得終止」（may terminate）。", "tip": "", "a": "5973bb24d085", "az": "18da615bf618"}, {"w": "of no force and effect", "pos": "adj. phr.", "zh": "不再生任何效力", "syn": "null and void／without effect", "tip": "void and of no force and effect 是典型的英美法同義詞堆疊，意思只有一個：無效。", "trap": "", "a": "db4bfff23b7f", "az": "f26bd290e17d"}, {"w": "certificate", "pos": "n.", "zh": "證書", "syn": "secretary's certificate／officer's certificate", "tip": "由公司秘書或高階主管出具，證明決議、章程、授權人等文件為真，是交割日文件包（closing documents）的常客。", "trap": "", "a": "4c6dcee98cf7", "az": "15f41c2990e1"}, {"w": "the Secretary", "pos": "n.", "zh": "公司秘書", "trap": "不是「秘書」職員。英、港、星公司法下的 Company Secretary 是法定職位，負責公司登記文件與決議紀錄。", "syn": "", "tip": "", "a": "302794c3410a", "az": "0d1b9644e4d1"}, {"w": "resolutions of the Board of Directors", "pos": "n. phr.", "zh": "董事會決議", "syn": "board resolutions", "tip": "授權簽約的核心文件；與「簽字能力及授權」那一節互相呼應。", "trap": "", "a": "85aef12ea578", "az": "b515ba5d76b9"}, {"w": "true, complete and correct copy", "pos": "n. phr.", "zh": "真實、完整且正確的副本", "tip": "三個形容詞缺一不可：true（真實）、complete（完整，沒抽頁）、correct（正確，沒改字）。", "syn": "", "trap": "", "a": "7469d4532c0a", "az": "fed5be0da15b"}, {"w": "authorizing among other things", "pos": "phr.", "zh": "授權（包括但不限於）…", "syn": "including without limitation", "tip": "among other things＝除此之外還有別的，等於 inter alia。", "trap": "", "a": "4b368b8bf9e2", "az": "6a8f168e69dd"}, {"w": "execution, delivery and performance", "pos": "n. phr.", "zh": "執行（簽署）、交付及履行", "trap": "英美合約的三部曲：execution（簽署）→ delivery（交付）→ performance（履行）。授權決議三者都要寫到，少一個就可能被質疑授權不足。", "syn": "", "tip": "", "a": "d11b649534d9", "az": "84bb6fbdd899"}, {"w": "amended, modified, revoked or rescinded", "pos": "v. phr.", "zh": "修訂、更改、撤銷或撤回", "tip": "四個動詞把「決議被動過手腳」的各種可能都蓋住。", "syn": "", "trap": "", "a": "2ea7f21083a4", "az": "49260879bea5"}, {"w": "since the dates on which they were adopted", "pos": "phr.", "zh": "自決議（通過）日起", "tip": "adopt a resolution＝通過決議。", "syn": "", "trap": "", "a": "eeb7a7225594", "az": "3fe53ef7b5eb"}, {"w": "as applicable", "pos": "phr.", "zh": "（視情形）如適用者", "syn": "where applicable／if applicable", "tip": "用於一句話套用到多個主體或情形時，表示只適用於相符者。", "trap": "", "a": "1539620d4c64", "az": "69a4686117d1"}]}]}, {"code": "3-4-4", "ch": "Chapter 參　基本條款", "sec": "四、合約效力及內容範圍（Contract Effectiveness）", "title": "效力保留 Survivorship 與合約可分性 Severability", "items": [{"k": "lead", "t": "兩個長得很像、效果卻不同的條款：效力保留處理「合約結束後，哪些條款還活著」；合約可分性處理「一條無效時，其他條款還算不算數」。一個管時間，一個管空間，審約時常被放在一起但千萬別混。"}, {"k": "h1", "t": "㈣效力保留條款（Survivorship）", "ic": "⏳"}, {"k": "p", "t": "於合約根據雙方的約定終止或者失效時，合約中的某些條款可以約定並不隨著合約的失效而終止其效力，而是根據本身的權利義務關係是否最終解決或雙方之合意而決定其效力期間。效力保留條款（survivorship）的目的，是確認此等條款的效力不受合約本身失效而受影響。"}, {"k": "p", "t": "最典型的可以適用效力保留的條款，是各種對違約行為的追索和救濟條款，如債務的追索、損害的賠償及法律救濟等，保證合約當事人的正當權利不會因為合約本身的失效或終止而喪失，或是對保密條款之執行等。"}, {"k": "en", "sp": "效力保留", "t": "Sections 5(a), 5(c), 6, 7, 12, 14, 16, 18 and 20 to 33 hereof **shall survive** the **expiration or termination** of this Agreement and shall continue **for so long as stated therein**.", "zh": "第 5(a)、5(c)、6、7、12、14、16、18 條及第 20 條至第 33 條規定，即便於本合約失效或終止後，仍持續有效存在。", "a": "2934a6773d9f"}, {"k": "p", "t": "在這個條款之下，當事人約定，本合約的第 5(a)、5(c)、6、7、12、14、16、18 以及第 20 條至第 33 條的約定，即使這個合約已失效或已終止，仍然有其效力。假設效力保留條款內容為有關會計事項、智慧財產權、保密義務、陳述、補償、合約可分性、仲裁條款、準據法等時，就代表這些相關條款下所記載的義務或事項，於合約已經結束或終止，雙方當事人仍然受其拘束。"}, {"k": "tip", "t": "效力保留條款的目的，在於確保一些**具有持續性的事項**（例如對違約之追索、智慧財產權、資訊保密義務等），在合約結束之後，仍然需依原來的約定繼續執行。審約時務必逐條核對清單：**保密、智財、補償、仲裁、準據法、通知**這六項幾乎一定要留下來。"}, {"k": "h1", "t": "㈤合約可分性條款（Severability）", "ic": "✂️"}, {"k": "p", "t": "與前面提到的「效力保留條款」相似，但效果又有所不同的條款，係所謂的「合約可分性條款」（Severability）。合約可分性條款存在的目的，是在於增加合約的靈活性，該條款規定的是合約中涉及的各種權利義務關係是否可以區分對待。也就是說，在合約中某些權利義務關係因為某些事件失效的情形下，合約中其他權利義務關係是否可以於合約約定的期間內繼續生效。"}, {"k": "en", "sp": "寫法一", "t": "If any provision of this Agreement shall be construed by **a court of competent jurisdiction** to be **illegal, invalid or unenforceable**, such provision **shall be deemed stricken and deleted** from this Agreement to the same extent and effect as if never incorporated herein, but all other provisions of this Agreement which is not found to be illegal, invalid or unenforceable in part shall continue in full force and effect.", "zh": "若本合約中任何條款，被具管轄權法院解釋為**非法、無效或不可被執行**，則此條款將被視為由本合約中刪除，**視為其從未被納入過**；但本合約之其他仍屬合法、有效且可被執行的條款，仍視為具完全的效力。", "a": "2ba0f1a22c20"}, {"k": "en", "sp": "寫法二", "t": "If any provision of this Agreement becomes invalid, illegal or unenforceable **in any respect** under any law, the **validity, legality and enforceability** of the remaining provisions shall not in any way be **affected or impaired**.", "zh": "若本合約的任何條款因任何法律變成無效、非法或不可被執行，則合約其他條款的效力、適法性以及可被執行性並不受影響。", "a": "f2ae564e779b"}, {"p": "", "k": "p", "t": "因此，合約可分性條款的目的，就在於確保，如果合約中一部分的條款，因為某些法律上的原因（例如法律的變動），而可能成為無效的時候，合約的其他條款仍然有效，而無效的條款則視為未存在。"}, {"k": "p", "t": "這與我國的民法第 111 條：「法律行為之一部分無效者，全部皆為無效。但除去該部分亦可成立者，則其他部分，仍為有效。」的規定相符合。"}, {"k": "tip", "t": "⚠ 我國民法第 111 條的原則其實是「**一部無效，全部無效**」，但書才是「除去該部分亦可成立者，其他部分仍為有效」。所以合約可分性條款在我國法下很有用——它等於當事人**事先表明意思**：請把壞掉的那條切掉就好，其餘留著。"}, {"k": "voc", "v": [{"w": "survivorship / survival clause", "pos": "n. phr.", "zh": "效力保留條款", "syn": "Survival of Terms", "tip": "動詞形式更常見：Sections X shall **survive** the expiration or termination of this Agreement。", "trap": "", "a": "5249caabdddf", "az": "227542f8753a"}, {"w": "shall survive", "pos": "v. phr.", "zh": "（於合約終止後）仍持續有效", "trap": "survive 不是「倖存」的字面意思，而是「不因合約終止而失效」。這是合約英文裡最漂亮的一個動詞。", "syn": "", "tip": "", "a": "4bb6c7c90116", "az": "d94a6cc3a8db"}, {"w": "expiration or termination", "pos": "n. phr.", "zh": "期間屆滿或終止", "trap": "兩者不同：expiration＝期間自然屆滿；termination＝提前終止。效力保留條款兩者都要寫，少一個就有漏洞。", "syn": "", "tip": "", "a": "5557777be12b", "az": "2a264a8ef638"}, {"w": "for so long as stated therein", "pos": "phr.", "zh": "依各該條款所載之期間持續", "tip": "therein＝in those sections。保密義務常另訂五年、十年或永久。", "syn": "", "trap": "", "a": "25454aab138f", "az": "bc6684a4c815"}, {"w": "severability", "pos": "n.", "zh": "（合約的）可分性", "syn": "Severance／Partial Invalidity", "tip": "條款標題常見 Severability 或 Severance。", "trap": "", "a": "eac2fc1b5e8c", "az": "a0dd3ac8fa79"}, {"w": "a court of competent jurisdiction", "pos": "n. phr.", "zh": "具管轄權之法院", "syn": "competent court", "tip": "固定用語，不要寫成 a competent court 以外的變形。", "trap": "", "a": "4004c4c8c21e", "az": "03a6bd37cb48"}, {"w": "illegal, invalid or unenforceable", "pos": "adj. phr.", "zh": "非法、無效或不可被執行", "trap": "三個層次不同：illegal（違法）、invalid（無效）、unenforceable（有效但法院不予強制執行）。三個都要寫才周延。", "syn": "", "tip": "", "a": "b236347370d9", "az": "5587c38f534d"}, {"w": "shall be deemed stricken and deleted", "pos": "v. phr.", "zh": "視為（由本合約）刪除", "syn": "shall be severed／shall be deemed deleted", "tip": "deem＝視為（法律擬制），合約中極高頻。", "trap": "", "a": "fdea2030338f", "az": "a9a08ff67829"}, {"w": "as if never incorporated herein", "pos": "phr.", "zh": "視為其從未被納入過", "syn": "as if it had never been included", "tip": "把效果拉回到最初，而不是只往後失效。", "trap": "", "a": "6afd9fecee41", "az": "1d649123d8a3"}, {"w": "continue in full force and effect", "pos": "v. phr.", "zh": "仍具完全的效力", "syn": "remain in full force and effect", "tip": "合約最常見的套語之一，簡寫 FFE。", "trap": "", "a": "1beeb3a916c6", "az": "1ef2b0b74513"}, {"w": "in any respect", "pos": "phr.", "zh": "於任何方面", "syn": "in whole or in part", "tip": "擴大適用範圍的修飾語。", "trap": "", "a": "8ca73bbef842", "az": "7dc0697506e2"}, {"w": "validity, legality and enforceability", "pos": "n. phr.", "zh": "效力、適法性及可被執行性", "tip": "與 illegal, invalid or unenforceable 是同一組概念的名詞形，成對記。", "syn": "", "trap": "", "a": "649a3fc0f95d", "az": "4314af97e727"}, {"w": "affected or impaired", "pos": "v. phr.", "zh": "受影響或減損", "syn": "prejudiced", "tip": "shall not in any way be affected or impaired＝不受任何影響。", "trap": "", "a": "c7ee9a5475b0", "az": "9363a73df724"}, {"w": "blue-pencil", "pos": "v.", "zh": "（法院）刪修無效條款", "trap": "進階概念：有些法域法院只肯「刪掉」不肯「改寫」。所以條款最好加一句「以最接近原意的有效條款取代」（replaced with a valid provision that most closely reflects the original intent）。", "syn": "", "tip": "", "a": "246c6440891b", "az": "3be31366c336"}]}]}, {"code": "3-4-5", "ch": "Chapter 參　基本條款", "sec": "四、合約效力及內容範圍（Contract Effectiveness）", "title": "期間及續約 Term and Renewal：合約活多久、怎麼自動展延", "items": [{"k": "lead", "t": "合約什麼時候到期？到期之後會不會自己續下去？期間條款與續約條款就是在處理這兩件事。本單元讀一則「一年期＋九十日前書面通知否則按月自動展延」的標準條款，並對照我國民法第 102 條。"}, {"k": "h1", "t": "期間與續約條款的功能", "ic": "📘"}, {"k": "p", "t": "合約的期間條款，規定了合約於何時到期，如何認定合約的到期，以及在合約到期時如何延長合約的期間。", "a": "f2a5305d5dfa"}, {"k": "p", "t": "合約會因為以下幾種情況到期：首先是法定的合約期限，由適用的法律來規定某些合約不得超過一定的年限；其次，是雙方約定的期限，合約雙方在合約中議訂合約的期限；第三，無期限合約，但是雙方可以在合約中加入合約終止條款（terminations），規定在何種情形下合約可以終止。", "a": "3974ce5355e6"}, {"k": "p", "t": "而續約條款係規範在合約期限到期之時，合約雙方根據何種條件為合約的續約。", "a": "c0967633b3c4"}, {"k": "tip", "t": "三種到期型態要分清楚：**①法定期限**（法律限制最長年限）**②約定期限**（雙方自己訂）**③無期限但有終止條款**。第三種最容易被誤以為「永久有效」，其實是靠 termination clause 來收尾。", "a": "4108573d3231"}, {"k": "h1", "t": "範例・期間及續約條款", "ic": "📅"}, {"k": "en", "sp": "標題", "t": "Term", "zh": "期間", "a": "5e86ecf11a16"}, {"k": "en", "sp": "(a) 期間", "t": "(a) The term of this Agreement shall be for one (1) year **commencing on** the 1st day of August 2012 and **terminating on** the 31st day of July, 2013 (the \"Term\"), **unless otherwise terminated pursuant to this Agreement**.", "zh": "(a) 本合約之期間為一年，自 2012 年 8 月 1 日起算，至 2013 年 7 月 31 日止（以下稱「期間」），除非另外有依本合約之約定終止本合約。", "a": "3fb248aff958"}, {"k": "en", "sp": "(b) 自動展延", "t": "(b) Unless terminated or unless either party has given the other at least ninety (90) days written **notice of its intention to terminate** the Agreement prior to expiration, then the Term shall **automatically be extended** **from month to month** after its expiration.", "zh": "(b) 除非依本合約約定終止本合約，或任一方當事人於合約期間終止前九十日以**書面通知**他方，則本合約之期間將自**期間屆滿**時起每月展延。", "a": "505c5e5cb6f0"}, {"k": "p", "t": "這個條款的目的基本上有兩個，第一個目的在於說明，這份合約的期間為一年，並特別指明開始及終止的日期，以免爭議；其次，這個條款也約定，原則上本合約於期限屆滿之後，會自動按月展延，除非當事人有提前以書面通知他方，這就是自動展延的條款。"}, {"k": "tip", "t": "自動展延條款的三個關鍵數字要一起看：**展延單位**（from month to month 按月／year to year 按年）、**通知期間**（at least ninety days）、**通知方式**（written notice）。少看一個，就可能錯過退出的時間窗，被自動綁下一期。"}, {"k": "h1", "t": "我國法對照：民法第 102 條", "ic": "⚖️"}, {"k": "p", "t": "在我國法下，依民法第 102 條第 1 項及第 2 項的規定：「附始期之法律行為，於期限屆至時，發生效力。」「附終期之法律行為，於期限屆滿時，失其效力。」", "a": "236d31bb09b7"}, {"k": "p", "t": "在一份合約之中，雖然合約的簽字日不必然為合約的生效日，惟除非有特別約定，合約通常係自簽約日生效（as of the date hereof）。我國民法雖然沒有針對「展延」有特別的規定，不過原則上如果當事人如上述條款有自動展延的約定，我國法院也會予以尊重。", "a": "0dba5eedaddf"}, {"k": "voc", "v": [{"w": "term", "pos": "n.", "zh": "（合約）期間", "trap": "注意一字多義：**the Term**（大寫，合約期間）／**terms**（條款）／**terms and conditions**（條款）。讀合約時看大寫與單複數分辨。", "syn": "", "tip": "", "a": "28011733beeb", "az": "20db0da43f37"}, {"w": "commencing on", "pos": "v. phr.", "zh": "自…起算", "syn": "starting from／with effect from", "tip": "commence＝開始（正式用語），合約中幾乎不用 start。", "trap": "", "a": "d364ec565fa7", "az": "5b80a3d7caf0"}, {"w": "terminating on", "pos": "v. phr.", "zh": "至…止", "syn": "expiring on／ending on", "tip": "期間一定要寫明起訖日，書中說「特別指明開始及終止的日期，以免爭議」。", "trap": "", "a": "5e616e22a67e", "az": "dc786e89bd41"}, {"w": "unless otherwise terminated pursuant to this Agreement", "pos": "phr.", "zh": "除非另依本合約之約定終止", "tip": "把提前終止的可能性保留下來，避免與終止條款衝突。", "syn": "", "trap": "", "a": "a0f10d07e09b", "az": "babb0f6be462"}, {"w": "written notice", "pos": "n. phr.", "zh": "書面通知", "syn": "notice in writing", "trap": "要回頭看 Notices（通知）條款：書面包不包括 email？送達以寄出日還是收到日為準？這決定九十日怎麼算。", "tip": "", "a": "5aef0b83c8c6", "az": "79e495f85336"}, {"w": "notice of its intention to terminate", "pos": "n. phr.", "zh": "終止意思之通知", "syn": "notice of non-renewal", "tip": "不續約通知與終止通知在實務上常混用，條款怎麼寫就怎麼算。", "trap": "", "a": "db8e8a7a5852", "az": "b406f2001b76"}, {"w": "prior to expiration", "pos": "prep. phr.", "zh": "於期間屆滿前", "syn": "before the expiry of the Term", "tip": "與 Long Stop Date 一樣，時點是爭議核心。", "trap": "", "a": "bd2e57e697bc", "az": "98193d067d83"}, {"w": "automatically be extended", "pos": "v. phr.", "zh": "自動展延", "syn": "shall automatically renew／evergreen clause", "trap": "俗稱 **evergreen clause（長青條款）**。錯過通知期間就被綁下一期，是最常見的商務地雷。", "tip": "", "a": "b6c0da386a71", "az": "ebc43ea2740d"}, {"w": "from month to month", "pos": "phr.", "zh": "按月（展延）", "syn": "from year to year／for successive one-year periods", "tip": "展延單位決定你下次能退出的時間點。", "trap": "", "a": "69bc21ea1188", "az": "be3ba0e58670"}, {"w": "expiration", "pos": "n.", "zh": "期間屆滿", "syn": "expiry（英式）", "trap": "expiration（自然屆滿）≠ termination（提前終止），兩者在效力保留、違約金、通知條款的效果都不同。", "tip": "", "a": "bc8cc55dc298", "az": "fa432d1a0b64"}, {"w": "termination clause", "pos": "n. phr.", "zh": "終止條款", "syn": "termination for convenience（任意終止）／termination for cause（有因終止）", "tip": "無期限合約就是靠終止條款收尾，規定在何種情形下合約可以終止。", "trap": "", "a": "531709fc7b59", "az": "6d98be12c38c"}, {"w": "renewal", "pos": "n.", "zh": "續約", "syn": "extension／roll-over", "tip": "renewal 通常指成立新期間，extension 指延長原期間，審約時看定義怎麼寫。", "trap": "", "a": "5690da8ac4d2", "az": "cecaaa3a140f"}, {"w": "as of the date hereof", "pos": "phr.", "zh": "自本合約簽約日起", "syn": "with effect from the date of this Agreement", "tip": "書中點出：合約的簽字日不必然為生效日，惟除非有特別約定，通常自簽約日生效。", "trap": "", "a": "4a6141ed06a0", "az": "8e60edbace4c"}, {"w": "附始期／附終期", "pos": "n. phr.", "zh": "民法§102 的始期與終期", "tip": "附始期之法律行為於期限屆至時發生效力；附終期之法律行為於期限屆滿時失其效力。", "syn": "", "trap": "", "a": "b8733259cb1e", "az": "5761d08c412d"}]}]}, {"code": "3-4-6", "ch": "Chapter 參　基本條款", "sec": "四、合約效力及內容範圍（Contract Effectiveness）", "title": "簽字能力與授權、基準語言、副本條款", "items": [{"k": "lead", "t": "三個「簽名當下」的條款：誰有權簽（Authorization）、哪一個語言版本說了算（Language）、要簽幾份、傳真算不算數（Counterpart）。看似瑣碎，但簽錯人、譯錯字、份數不對，整份合約都可能執行不了。"}, {"k": "h1", "t": "㈦簽字能力及授權（Authorization and Ability to Execute）", "ic": "✍️"}, {"k": "p", "t": "如果當事人的一方是法人或代表簽約的不是當事人本人時，就會有簽約者簽字能力的問題。一般而言，合約必須經過合約雙方的授權代表簽字後才正式生效，因此要求合約雙方派出的代表必須是具有完全民事行為能力、可以簽署合約，並且獲得其所代表當事人之合法且完整授權之人。"}, {"k": "p", "t": "反之，合約如果不是由具有合法授權的簽字能力的人簽約時，該合約仍然可能對一方或雙方當事人不發生效力。簽字能力條款的目的，就在於確保合約是由具合法授權可簽字的人所簽署。"}, {"k": "en", "sp": "簽字授權", "t": "Each party **represents that** its **undersigned officer** is **duly authorized** to sign this Agreement on its behalf.", "zh": "本合約任一當事人皆保證下列簽名的人員，皆**經合法**授權以**代表其**簽訂本合約。", "a": "1be4b1fb3c22"}, {"k": "p", "t": "於上述條款中，雙方當事人皆陳述（representation），於合約上簽名的人，皆經合法授權。由於其係架構為「表述」，如果事後發現當事人一方簽名的人未經合法授權而導致合約無法被執行時，則他方當事人，可以主張終止合約（必須視合約的準據法而定）或請求損害賠償。"}, {"k": "tip", "t": "注意這一句的架構是 **represents（表述）**，不是單純的事實敘述。因為架構成表述，一旦不實就同時觸發「不實陳述」與「違約」兩條救濟路線——這正是把它寫進合約的用意。實務上另外還要收**董事會決議**與**授權書**（見解除條件那一單元的 certificate）。"}, {"k": "h1", "t": "㈧基準語言（Language）", "ic": "🌐"}, {"k": "p", "t": "基準語言條款說明了合約本文應當使用的語言，以及何種語言的版本為最終有效之基準。英文合約一般約定以英文版本為有效基準版本，如果對文字有任何爭議，需以有效基準之版本內容為主。在當事人使用的語言有不同時，就有可能需要設計基準語言條款，以避免翻譯所造成的差異。"}, {"k": "en", "sp": "基準語言", "t": "This Agreement has been **written and negotiated in English** between the Parties. Any translation of this Agreement into a language other than English (including Mandarin Chinese) is **for reference only**. **In the event of conflict between versions**, this English version shall govern.", "zh": "本合約以英文撰寫並於雙方間以英文協商。任何本合約英文以外語言（包括中文）之翻譯文**僅供參考之用**。如不同語言版本間有任何歧異，以英文本為準。", "a": "f3ff495313d7"}, {"k": "p", "t": "在這個條款之下，當事人約定合約文字及合約的協商所使用的語言為英文，且任何翻譯本與英文原本的文義有差距時，合約的解釋應以英文為準，因此，任何翻譯本僅供參考之用，並不足以產生影響合約的效力。"}, {"k": "tip", "t": "⚠ 對台灣當事人最實際的風險：**你讀的中文版只是參考**。談判時若中文版才是你真正理解的版本，就要爭取「中文版為準」或「兩版本同等效力」（equally authentic），否則出事時以英文版論。"}, {"k": "h1", "t": "㈨副本條款（Counterpart）", "ic": "📑"}, {"k": "p", "t": "副本條款係指合約雙方代表簽字的原始副本的份數，一般至少兩份以上，以及此等副本的效力如何。通常情況下，經過合約雙方代表簽字的所有原始副本具有相同的法律效力。此外，一份合約如果超過一頁時，有時會要求在各頁騎縫處用印，以避免將來的爭議。"}, {"k": "en", "sp": "標題", "t": "Effectiveness and Miscellaneous", "zh": "效力及其他", "a": "47424b2ba2bd"}, {"k": "en", "sp": "(a) 簽名用印", "t": "(a) This Contract shall come into effect upon **signatures and seals** by both parties. If the Contract has more than one page, then each page should be **sealed on the perforation**.", "zh": "(a) 本合約在經雙方當事人**簽名及用印**之後發生效力。如果本合約超過一頁時，則各頁皆應**於頁縫處用印**。", "a": "7f6c8f3e315f"}, {"k": "en", "sp": "(b) 一式四份", "t": "(b) This Contract shall be **executed in four counterparts** with same legal effect, with each of the parties hereto holding two; each party shall send the original copy to the other party **within 3 working days upon execution**. The copy **delivered through telefax** shall be as valid as the original.", "zh": "(b) 本合約應作一式四份，每份皆具相同之法律效力，雙方當事人各執二份。各當事人應將其中一份於簽名後三個工作日內寄達他方，**以傳真方式傳送**者與原本有一樣的效力。", "a": "14c30d4261a2"}, {"k": "p", "t": "這個條款分為兩個部分，第一部分就是在約定合約應簽名及用印，且超過一頁時，應在各頁間的頁縫處用印。第二部分就是副本的問題，這也是在解決遠距簽約（或當事人無法當面簽名時）的問題，依上述條款約定，本合約分一式四份，各當事人各執二份，需注意皆須簽名及用印並加騎縫章，始為完整有效的合約。"}, {"k": "voc", "v": [{"w": "undersigned officer", "pos": "n. phr.", "zh": "下列簽名之人員（主管）", "syn": "the undersigned／authorised signatory", "tip": "undersigned＝在下面簽名的人，法律文件的固定用語。", "trap": "", "a": "a2d2b9dbe4a7", "az": "52ce32e4e20f"}, {"w": "duly authorized", "pos": "adj. phr.", "zh": "經合法（正式）授權", "syn": "validly authorised／properly empowered", "trap": "duly 這個字在合約裡到處都是（duly incorporated、duly executed、duly performed），意思是「依法定程序、妥適地」。", "tip": "", "a": "7298e19121f3", "az": "385f12c44a9b"}, {"w": "on its behalf", "pos": "prep. phr.", "zh": "代表其（公司）", "syn": "for and on behalf of", "tip": "簽名頁的標準寫法：For and on behalf of ABC Limited。", "trap": "", "a": "671c59549825", "az": "c1a7e58ccd7a"}, {"w": "represents that", "pos": "v.", "zh": "表述；陳述", "trap": "關鍵：寫成 represents 就會同時觸發**不實陳述**與**違約**兩條救濟路線；若只寫成事實敘述，效果就弱得多。", "syn": "", "tip": "", "a": "eab7df82a4b0", "az": "b94758d012af"}, {"w": "written and negotiated in English", "pos": "v. phr.", "zh": "以英文撰寫並協商", "tip": "同時綁住「文本語言」與「協商語言」，避免對方主張他是用別的語言談的。", "syn": "", "trap": "", "a": "0432d773e521", "az": "cc59ba8f8a86"}, {"w": "for reference only", "pos": "phr.", "zh": "僅供參考之用", "trap": "看到翻譯本被寫成 for reference only，就代表**你讀的中文版沒有法律效力**。這是台灣當事人最常踩的雷。", "syn": "", "tip": "", "a": "4ad0ac40db4e", "az": "fb5f599dd8bb"}, {"w": "in the event of conflict between versions", "pos": "phr.", "zh": "如不同版本間有歧異時", "syn": "in case of any discrepancy between the two versions", "tip": "與優先順序條款同一個句型家族。", "trap": "", "a": "586d0173cd12", "az": "c9a183af0ccf"}, {"w": "shall govern", "pos": "v. phr.", "zh": "以…為準；適用之", "syn": "shall prevail／shall control", "tip": "也用於準據法條款：This Agreement shall be governed by the laws of…", "trap": "", "a": "d7d05ba7a038", "az": "3276b812ff69"}, {"w": "equally authentic", "pos": "adj. phr.", "zh": "同等效力（版本）", "tip": "雙語合約若要兩版同等效力就寫這個，但隨之而來的是雙版本必須字字對齊的風險。", "syn": "", "trap": "", "a": "b8c78818b046", "az": "085d792d768e"}, {"w": "counterpart", "pos": "n.", "zh": "副本（各自簽署的同一份合約）", "trap": "不是「影本」。counterpart 是各方各簽一份、合起來構成同一份合約，是遠距簽約的法律基礎。", "syn": "", "tip": "", "a": "64fab0f7927d", "az": "189c1745cee0"}, {"w": "executed in four counterparts", "pos": "v. phr.", "zh": "作成一式四份", "syn": "executed in any number of counterparts", "tip": "execute 在合約中是「簽署」，不是「執行」或「處決」。", "trap": "", "a": "fc3df746244b", "az": "bce494ddef86"}, {"w": "with same legal effect", "pos": "phr.", "zh": "每份具相同之法律效力", "syn": "each of which shall be deemed an original", "tip": "標準美式寫法：each of which shall be deemed an original, and all of which together shall constitute one and the same instrument.", "trap": "", "a": "efcbc8b022cd", "az": "a83fc485f242"}, {"w": "signatures and seals", "pos": "n. phr.", "zh": "簽名及用印", "trap": "華人圈交易常要求簽名**加**公司大小章；英美合約通常只要簽名。兩邊習慣不同，要在條款裡講清楚。", "syn": "", "tip": "", "a": "359b7fc98dce", "az": "0285dad62dcb"}, {"w": "sealed on the perforation", "pos": "v. phr.", "zh": "於頁縫處用印（騎縫章）", "tip": "防止抽換頁面，超過一頁的合約務必加。", "syn": "", "trap": "", "a": "05eeea509716", "az": "caeb29c25d3d"}, {"w": "within 3 working days upon execution", "pos": "phr.", "zh": "於簽署後三個工作日內", "syn": "business days", "trap": "working days／business days 要定義（哪一地的營業日？遇假日怎麼算？），否則又是爭點。", "tip": "", "a": "523870221faa", "az": "0b96f55dbc05"}, {"w": "delivered through telefax", "pos": "v. phr.", "zh": "以傳真方式傳送", "syn": "by facsimile／by electronic signature（現代版）", "tip": "現在的對應條款會寫 PDF、DocuSign 等電子簽章與正本有同等效力。", "trap": "", "a": "a8c98bb3b22e", "az": "bb068e490bc6"}]}]}, {"code": "3-4-7", "ch": "Chapter 參　基本條款", "sec": "四、合約效力及內容範圍（Contract Effectiveness）", "title": "合約的解釋方式 Construction, Interpretation", "items": [{"k": "lead", "t": "定型化合約或由一方準備的標準範本，法院有時會作成對某一方有利或不利的解釋。解釋條款就是當事人事先就「怎麼讀這份合約」作成約定。本單元讀三個例子：共同準備、單複數與陰陽性、標題不影響解釋，並對照民法第 247 條之 1 與消保法第 12 條。"}, {"k": "h1", "t": "為什麼要約定解釋方式", "ic": "📘"}, {"k": "p", "t": "有時合約當事人會就合約解釋的基本原則作約定，以避免合約對一方作有利或不利的解釋，特別是在合約可能是定型化合約，或由一方當事人所準備好的標準範本的時候，如果沒有特別約定的時候，有時法院會傾向對某方當事人為有利的方式為解釋。", "a": "bf8dcde3bfca"}, {"k": "p", "t": "無論是在我國還是在英美諸國，一般而言，於契約法下，會視當事人是一般消費者還是商業團體而調整契約自由的範圍，以維護消費者的權益以及公平正義。因此，如果英文合約是涉及消費交易，即便準據法是英國、美國或其他國家，或合約中有解釋條款，我國的法院仍然有介入的空間，這是在撰擬或閱讀合約以及設計交易架構時，必須特別注意的地方。", "a": "94401ad1f3c4"}, {"k": "tip", "t": "⚠ 這是全章最重要的實務提醒：**消費交易即使約定外國準據法，我國法院仍有介入空間**。民法第 247 條之 1 與消保法第 12 條都可以讓顯失公平的條款部分（甚至全部）無效。", "a": "3927a10e8709"}, {"k": "h1", "t": "我國法的兩道防線", "ic": "⚖️"}, {"k": "p", "t": "民法第 247 條之 1：「依照當事人一方預定用於同類合約之條款而訂定之合約，為左列各款之約定，按其情形顯失公平者，該部分約定無效：一、免除或減輕預定合約條款之當事人之責任者。二、加重他方當事人之責任者。三、使他方當事人拋棄權利或限制其行使權利者。四、其他於他方當事人有重大不利益者。」", "a": "c11438d4a339"}, {"k": "p", "t": "消費者保護法第 12 條：「定型化合約中之條款違反誠信原則，對消費者顯失公平者，無效。定型化合約中之條款有下列情形之一者，推定其顯失公平：一、違反平等互惠原則者。二、條款與其所排除不予適用之任意規定之立法意旨顯相矛盾者。三、合約之主要權利或義務，因受條款之限制，致合約之目的難以達成者。」", "a": "08a0958bd33a"}, {"k": "p", "t": "這兩條的規定的內容差別不大，但主要皆表明，如果合約的內容有顯失公平的時候，法院有可能使合約的一部分（甚至全部）變為無效。我國的法院也不乏有利用前面兩條的規定，使合約的一部分變為無效的案例（例如最高法院 91 年臺上字第 1577 號判決，有關認定飯店業者提供停車服務，但不負任何保管責任條款之無效）。", "a": "d749f3fe1485"}, {"k": "h1", "t": "例一・共同準備", "ic": "🤝"}, {"k": "p", "t": "當事人可以約定，合約的條款是雙方共同準備的，以避免在合約有爭議的時候，以此為理由作為對一方不利解釋的依據，例如："}, {"k": "en", "sp": "共同準備", "t": "This Agreement **shall be deemed to have been prepared jointly** by the parties hereof. Any **ambiguity** herein shall not be **interpreted against any party** hereto and shall be interpreted as if each of the parties had prepared this Agreement.", "zh": "本合約被視為係由本合約的當事人所共同準備。本合約若有任何**不明確之處**，不應被解釋為對任一方不利，而應在任一當事人共同準備這份合約的基礎上被解釋。", "a": "4b725b38f0e5"}, {"k": "p", "t": "如此一來，利用上述條款，無論實際上合約條款是不是共同準備及撰擬的，但至少約定合約條款是共同準備，還是由一方當事人提供，所以不應該據此對任一方作不利益的解釋。一般而言，法院應該會尊重當事人的約定，但是實際上可能還是要視準據法國家的法律以及實際上交易的狀況而定；在商業交易上這種條款比較容易被接受，但如果是企業與消費交易的時候，仍然有被法院推翻的可能性。"}, {"k": "tip", "t": "這一條在對抗英美法的 **contra proferentem（不利於擬約人解釋）原則**。該原則是：條文有歧義時，對提供範本的一方作不利解釋。約定「共同準備」就是要排除它——但消費交易仍可能被推翻。"}, {"k": "h1", "t": "例二・單複數及陰陽性的解釋規則", "ic": "🔤"}, {"k": "p", "t": "當事人也可以明確約定合約應解釋的方式，有時可包含非常基本或技術面的問題，例如："}, {"k": "en", "sp": "單複數陰陽性", "t": "In this Agreement, **unless the context otherwise requires**, **words in the singular number include the plural**, and in the plural include the singular; and words of the masculine gender include the feminine and the neuter, and when the sense so indicates words of the neuter gender may refer to any gender.", "zh": "於本合約下，除非另有約定，以單數出現的字，其涵義包含複數，而複數出現的字，其涵義亦包括單數；且以陽性出現的字，其涵義亦包括陰性或中性的意義，且若一字係以中性出現，其涵義可包括任何性別。", "a": "804d685df3b8"}, {"k": "p", "t": "此種約定似乎流於瑣碎，然而此種條款並非每份合約都有，但有時為了避免單複數或陰陽性問題的爭議，有其約定之必要。"}, {"k": "h1", "t": "例三・標題（Heading or Title）", "ic": "🏷️"}, {"k": "p", "t": "在一份合約中，包含了形形色色的諸多條款，每個條款均有自己的標題，而標題的使用也是根據撰寫合約者的選擇而五花八門。標題條款的目的，是確認合約本身的各種條款的效力和意義，不應當受到所冠標題的任何影響，以排除因為使用不當標題而影響合約條款內容的可能性。例如："}, {"k": "en", "sp": "寫法一", "t": "The names of the parties, the date and **the preamble first above written** are part of this Agreement. The captions and section numbers appearing in this Agreement are **inserted only as a matter of convenience**. They **do not define, limit or describe the scope or intent** of the provisions of this Agreement.", "zh": "當事人的姓名、日期及合約的前言皆係本合約的一部分。本合約中所出現的標題或條號皆**僅係為便利所加入**，而未有定義、限制或描述本合約的條款的範圍或目的效果。", "a": "e20b6feb29ff"}, {"k": "en", "sp": "寫法二", "t": "The titles to the respective sections hereof **shall not be deemed a part of this Agreement** but shall be regarded as having been used for convenience only.", "zh": "任一條規定之標題，並**不構成本合約之一部分**，而僅係為便利而使用。", "a": "b33348c2cd94"}, {"k": "p", "t": "此條款一方面在確認合約中所載的當事人姓名、日期與前言部分具有合約的效力，但就有關標題與條號的部分，只是為方便加入，但不可以以標題的文字作為解釋合約內容的依據。"}, {"k": "p", "t": "依我國民法第 98 條規定，解釋合約，應探求當事人真意，故如當事人約定，合約的標題僅係為方便而使用，不構成合約的一部分時，我國法院應該尊重當事人的意思；反之，如果無特別約定時，法院仍有可能會參考標題的意義以方便為目的及體系解釋，因此，如果當事人不希望標題（甚至目錄或前言等）變成合約一部分的話，仍然有需要於合約中明白約定合約使用的標題不具有合約文字的效力。"}, {"k": "tip", "t": "注意寫法一的**前半段很重要**：它確認「當事人姓名、日期與前言」**是**合約的一部分（有效力），只有標題與條號不是。前言（Preamble／WHEREAS）到底算不算合約的一部分，就是靠這一句決定的——回頭看第一單元的 recitals。"}, {"k": "voc", "v": [{"w": "construction / interpretation", "pos": "n.", "zh": "（合約的）解釋", "trap": "construction 在合約裡是「解釋」，**不是建造**。shall not affect the construction of this Agreement＝不影響本合約之解釋。", "syn": "", "tip": "", "a": "5f9012039432", "az": "7d4e3e149c86"}, {"w": "定型化合約", "pos": "n. phr.", "zh": "standard form contract／adhesion contract", "tip": "由一方預定用於同類合約的條款，受民法§247-1 與消保法§12 檢驗。", "syn": "", "trap": "", "a": "068ae4f632bb", "az": "70bb1c4e187f"}, {"w": "contra proferentem", "pos": "（拉丁）", "zh": "不利於擬約人解釋原則", "tip": "條文有歧義時對提供範本的一方作不利解釋。「共同準備」條款就是為了排除它。", "syn": "", "trap": "", "a": "f792d4e9019d", "az": "bc8720a7b464"}, {"w": "shall be deemed to have been prepared jointly", "pos": "v. phr.", "zh": "視為由雙方共同準備", "syn": "jointly drafted", "tip": "法律擬制：不管實際上誰寫的，一律視為共同準備。", "trap": "", "a": "c5870e25d786", "az": "a126556bb52a"}, {"w": "ambiguity", "pos": "n.", "zh": "不明確之處；歧義", "syn": "vagueness／uncertainty", "tip": "Any ambiguity herein shall not be interpreted against any party hereto．", "trap": "", "a": "93051cba10a4", "az": "8608bfef127d"}, {"w": "interpreted against any party", "pos": "v. phr.", "zh": "作成對任一方不利之解釋", "tip": "against＝不利於。這就是 contra proferentem 的英文白話版。", "syn": "", "trap": "", "a": "2868ae9b57d7", "az": "855e4082353a"}, {"w": "words in the singular number include the plural", "pos": "phr.", "zh": "以單數出現的字其涵義包含複數", "syn": "the singular includes the plural and vice versa", "tip": "解釋條款最標準的一句，背起來。", "trap": "", "a": "4235ca710e97", "az": "77d6cf3644b6"}, {"w": "masculine / feminine / neuter gender", "pos": "n. phr.", "zh": "陽性／陰性／中性", "tip": "現代合約多改寫為 words importing one gender include every gender，更簡潔。", "syn": "", "trap": "", "a": "6bd370a7eb0e", "az": "9f8d74cf5830"}, {"w": "unless the context otherwise requires", "pos": "phr.", "zh": "除依上下文另有所指外", "tip": "與定義條款同一個安全閥，解釋條款也會用。", "syn": "", "trap": "", "a": "785953dffd67", "az": "2ae9f71a9703"}, {"w": "captions and section numbers", "pos": "n. phr.", "zh": "標題與條號", "syn": "headings／titles to the respective sections", "tip": "caption＝標題（美式用語）。", "trap": "", "a": "2e587af519d7", "az": "6536d24dc8b3"}, {"w": "inserted only as a matter of convenience", "pos": "phr.", "zh": "僅係為便利所加入", "syn": "for convenience of reference only", "tip": "標題條款的靈魂句。", "trap": "", "a": "8ffc8879fe88", "az": "616fb4f33349"}, {"w": "do not define, limit or describe the scope or intent", "pos": "v. phr.", "zh": "未有定義、限制或描述其範圍或目的", "tip": "三個動詞把標題可能產生的解釋影響全部排除。", "syn": "", "trap": "", "a": "e1f50f2fc808", "az": "4020524661f2"}, {"w": "the preamble first above written", "pos": "n. phr.", "zh": "文首所載之前言", "syn": "the recitals set out above", "trap": "這一句確認前言**是**合約的一部分——與第一單元 WHEREAS 不創設義務的原則要一起讀，決定前言在解釋上的地位。", "tip": "", "a": "f14e127b3316", "az": "4895566477e2"}, {"w": "shall not be deemed a part of this Agreement", "pos": "phr.", "zh": "不構成本合約之一部分", "tip": "用來把標題、目錄排除在合約文字之外。", "syn": "", "trap": "", "a": "13965057eae2", "az": "4934e821d3c3"}, {"w": "民法§98", "pos": "n. phr.", "zh": "解釋意思表示，應探求當事人之真意", "tip": "我國解釋合約的總則條文。當事人若已明約標題僅為便利，法院應尊重其意思。", "syn": "", "trap": "", "a": "a7c3e6608872", "az": "4ee3ffdbdabd"}, {"w": "民法§247-1", "pos": "n. phr.", "zh": "定型化契約條款顯失公平者無效", "tip": "四款：免除/減輕預定人責任、加重他方責任、使他方拋棄或限制權利、其他重大不利益。", "syn": "", "trap": "", "a": "e09a6c72e10e", "az": "a09cf9b910e4"}, {"w": "消保法§12", "pos": "n. phr.", "zh": "定型化契約條款違反誠信原則對消費者顯失公平者無效", "tip": "三款推定顯失公平：違反平等互惠、與任意規定立法意旨顯相矛盾、致契約目的難以達成。", "syn": "", "trap": "", "a": "d6edb4a92452", "az": "b51fd72651ae"}]}]}, {"code": "3-5-1", "ch": "Chapter 參　基本條款", "sec": "五、表述、保證與承諾（Representation, Warranty, Undertaking）", "title": "表述、保證與承諾 概說：三個字的法律效果不一樣", "items": [{"k": "lead", "t": "representation、warranty、undertaking 這三個字幾乎每份英文合約都有，中譯也常被混為一談，但它們的法律效果完全不同。本單元把三者的定義、違反時的救濟，以及 representation 與 warranty 在英美法下的特殊意義一次講清楚——這是整章最該背熟的觀念。"}, {"k": "h1", "t": "為什麼要有表述、保證與承諾條款", "ic": "📘"}, {"k": "p", "t": "合約的基礎是合約雙方的一致協議，即雙方對於交易所涉及的某些事實取得共識。如果合約中某一方向另一方所作的有關任何事實的表述與實際情況產生偏差，導致另一方依賴和信任該表述，而做出了締結合約的決定，就會出現交易偏差的問題。出現偏差，那麼就危及了另一方透過合約所要達到的商業目的，悖離公正公平的原則。", "a": "c33492051d54"}, {"k": "p", "t": "合約中的表述、保證和承諾條款，即是將合約雙方達成合約時所依賴的各種表述的事實（representations）、針對合約標的的交易之各種保證（warranties），和在針對合約做出的種種履行某種作為或者不作為的承諾（undertakings），完整清楚的規範於合約內。", "a": "16b694facefa"}, {"k": "p", "t": "倘若在合約簽訂生效之後，任何提及的事實表述，做出的保證或承諾，如與實際的事實不一致，或者無保證之效果，或為無法履行承諾之事項，那麼另一方可以按照合約的權利要求強制執行合約，或者按照合約的規定終止合約。", "a": "d9901726c726"}, {"k": "tip", "t": "三個字的分工：**representation ＝ 陳述「事實」**（過去／現在已存在的事實）；**warranty ＝ 對標的交易的「保證」**；**undertaking ＝ 承諾將來「作為或不作為」**。時間軸不同，救濟也不同。", "a": "73d111237042"}, {"k": "h1", "t": "典型會寫進去的事項", "ic": "📋"}, {"k": "p", "t": "合約雙方一般在表述、保證和承諾條款中所確認的事實、保證和承諾，可以包括以下事項，例如：確認合約係根據具有效力的法律，具有合法的資格進行交易；合約雙方也必須確認，其具有合法的和充分的授權來簽署合約；合約雙方保證履行合約中所涉及的關於交易的各種義務；或保證履行此合約不會損害任何協力廠商的利益或者違反任何公序良俗，以及合約雙方保證遵守相關的法律等。", "a": "bba6f316c0b0"}, {"k": "p", "t": "除了上述一般合約中需要具備的內容之外，本著締約自由的原則，合約雙方可以根據標的交易的具體情況和環境做出更多更具體的承諾。", "a": "bff6d383a8db"}, {"k": "h1", "t": "⚠ representation（表述）在英美法下的特殊意義", "ic": "🔍"}, {"k": "p", "t": "所謂的表述（representation），在英美法下有特別的意義。一般而言，「表述」指的是對過去「事實上」的陳述，所以一般而言表述係在陳明過去已經發生的事實。", "a": "199e60e7cddb"}, {"k": "p", "t": "如果表述的內容有不實或錯誤的時候，在英美法上，就有可能構成所謂的「不實陳述」（misrepresentation），視準據法國家之法律，可能可以撤銷（set aside, revoke）整個合約，或是請求損害賠償（例如依照英國的 Misrepresentation Act 1967），這是在載明「表述」的內容時，合約當事人所必須特別注意的地方。當然，除得依據法律行使相關權利之外，也同時會構成違反合約的情事，這也是將表述條款納入合約的用意之一。", "a": "528e8cfbe374"}, {"k": "p", "t": "最嚴重的不實陳述，就構成所謂的詐欺（fraud, deceit），至於依過失或係完全無過失的不實陳述的法律效果，就必須視合約準據法國家的法律而定。", "a": "a5a162cf0d08"}, {"k": "p", "t": "不過，「表述」這個概念係特別存在於英美法系的國家之中，所以英文合約也常會融入此一概念，但如果合約的準據法非為英美法系的國家時，則不一定會產生前述的不實陳述法律效果；然而，如果一方當事人構成詐欺時，於我國仍然可能可以依民法第 92 條的規定撤銷合約（是否適用我國民法仍需視準據法條款的文義及適用範圍而定）。", "a": "a41d2e4e5e0a"}, {"k": "tip", "t": "把不實陳述的三個層次記起來：**fraudulent（詐欺）＞ negligent（過失）＞ innocent（無過失）**，效果依準據法而不同。最嚴重者構成 fraud／deceit；在我國則可能依民法第 92 條（被詐欺或脅迫而為意思表示者，得撤銷之）撤銷。", "a": "a51ce411d3ed"}, {"k": "h1", "t": "⚠ warranty 的兩種意義", "ic": "🔍"}, {"k": "p", "t": "其次，「warranty」在英美契約法上至少有二種不同的意思。第一個層面，「warranty」指的是「非重要」的條款，是相對於前面提到的「condition」而言，在合約中並沒有特別約定的情況下，違反「warranty」條款不會使未違約的一方取得終止合約的權利（但仍然可以請求損害賠償）。", "a": "51d1a83a1558"}, {"k": "p", "t": "另一個層面，所謂的「warranty」，指的是「保證」或「擔保」，一般商品所提到的保固期間也屬於此類擔保，如果違反保證或擔保條款時，其法律效果需視合約是否有特別約定，一般而言，至少應可請求違約的損害賠償。", "a": "01029bfe851b"}, {"k": "p", "t": "表述和承諾的內容視交易及當事人的需求而定。", "a": "a8b3becb58dc"}, {"k": "tip", "t": "**condition vs warranty 對照表**：condition＝重要條款，違反 → 未違約方得**終止合約**＋損害賠償；warranty＝非重要條款，違反 → 原則上**只能請求損害賠償**，不能終止。這組對比在停止條件那一單元已經出現過，是英美合約法的基本功。", "a": "9e3342a644a8"}, {"k": "voc", "v": [{"w": "representation", "pos": "n.", "zh": "表述；陳述", "syn": "statement of fact", "trap": "指**過去已發生／現在存在的事實**之陳述。不實時構成 misrepresentation，可能撤銷合約或請求損害賠償。", "tip": "", "a": "38a9a6783653", "az": "b94758d012af"}, {"w": "warranty", "pos": "n.", "zh": "保證；擔保／非重要條款", "trap": "**兩種意思**：㈠相對於 condition 的「非重要條款」，違反只能請求損害賠償㈡「保證、擔保」，商品保固期間也屬此類。", "syn": "", "tip": "", "a": "7b851ab1f2af", "az": "068aa7288bd5"}, {"w": "undertaking", "pos": "n.", "zh": "承諾（將來為某作為或不作為）", "syn": "covenant", "tip": "時間軸指向未來，與 representation（過去事實）正好相對。", "trap": "", "a": "fd213afaa71c", "az": "72ffcac6c191"}, {"w": "misrepresentation", "pos": "n.", "zh": "不實陳述", "syn": "false statement", "trap": "三個層次：fraudulent（詐欺）／negligent（過失）／innocent（無過失），法律效果依準據法不同。英國有 Misrepresentation Act 1967。", "tip": "", "a": "3fc9b3f34158", "az": "3090f4bddaf0"}, {"w": "set aside / revoke / rescind", "pos": "v.", "zh": "撤銷（整個合約）", "syn": "avoid the contract", "tip": "不實陳述最強的效果就是把合約整個撤銷，回復到從未訂約的狀態。", "trap": "", "a": "a3e73c9d29b8", "az": "62dbe572de83"}, {"w": "fraud / deceit", "pos": "n.", "zh": "詐欺", "trap": "最嚴重的不實陳述。在我國可能依**民法第 92 條**（因被詐欺或被脅迫而為意思表示者，表意人得撤銷其意思表示）撤銷合約。", "syn": "", "tip": "", "a": "70082747ee6b", "az": "25b097ad69e5"}, {"w": "rely on / reliance", "pos": "v./n.", "zh": "依賴、信賴", "tip": "不實陳述成立的關鍵要件：對方**依賴和信任**該表述而做出締約決定。所以才會有 non-reliance clause（不信賴條款）來阻斷。", "syn": "", "trap": "", "a": "d596b2449549", "az": "76c795172dfa"}, {"w": "legal capacity to transact", "pos": "n. phr.", "zh": "進行交易之合法資格", "syn": "capacity and authority", "tip": "表述保證條款的第一組標準項目：合法設立、有資格交易。", "trap": "", "a": "10c98c61a2df", "az": "2fb2c3f763cc"}, {"w": "due and sufficient authority", "pos": "n. phr.", "zh": "合法且充分之授權", "syn": "duly authorised", "tip": "第二組標準項目，與「簽字能力及授權」那一單元互相呼應。", "trap": "", "a": "7303f4a147b2", "az": "c427515c3f21"}, {"w": "not infringe third party rights", "pos": "v. phr.", "zh": "不損害第三人（協力廠商）之利益", "syn": "non-infringement", "tip": "第三組標準項目，智財授權與代工合約的核心保證。", "trap": "", "a": "f8c97a2647bc", "az": "cead8d8862a6"}, {"w": "public order and good morals", "pos": "n. phr.", "zh": "公序良俗", "syn": "public policy", "tip": "第四組標準項目：保證履行合約不違反公序良俗。", "trap": "", "a": "13cf9ba19c83", "az": "ea84fccd8153"}, {"w": "comply with applicable laws", "pos": "v. phr.", "zh": "遵守相關（適用之）法律", "syn": "compliance with laws", "tip": "法遵條款的基本句，後面常接具體法規清單（見代工生產那一單元）。", "trap": "", "a": "e7063332abbb", "az": "f2263c868cb8"}, {"w": "specific performance", "pos": "n. phr.", "zh": "強制履行；特定履行", "syn": "enforce the contract", "tip": "書中所說的「按照合約的權利要求強制執行合約」。", "trap": "", "a": "6b42ae8ce6f1", "az": "9d3c6d39e7e7"}, {"w": "締約自由原則", "pos": "n. phr.", "zh": "freedom of contract", "tip": "除一般必備內容外，雙方可依交易的具體情況和環境做出更多更具體的承諾。", "syn": "", "trap": "", "a": "9f0a720cf1b1", "az": "01115e156cea"}]}]}, {"code": "3-5-2", "ch": "Chapter 參　基本條款", "sec": "五、表述、保證與承諾（Representation, Warranty, Undertaking）", "title": "例一：股份買賣的表述、保證及承諾", "items": [{"k": "lead", "t": "股權買賣的表述保證條款怎麼寫？本單元讀一則完整範例：先宣告附件三的保證在簽約日與完成日都真實正確（雙時點），再課賣方交割前的揭露義務，最後由買方反向作出自己的表述保證。一句英文一句中文對照。"}, {"k": "h1", "t": "(a) 保證之真實性（雙時點）", "ic": "✅"}, {"k": "en", "sp": "標題", "t": "Representations and Warranties", "zh": "表述及保證", "a": "c83058f668c0"}, {"k": "en", "sp": "(a) 真實正確", "t": "(a) The representations, warranties and undertakings **set out in Schedule 3** (**collectively, the \"Warranties\"**) given by Vendor to Purchaser are true and accurate **as of the date of this Agreement and as of the Completion Date** or 31 May 2012, whichever is earlier.", "zh": "(a) 於附件三中，由賣方給予買方之表述、保證或承諾（**合稱「保證」**）**於本合約簽訂之日及完成日**或 2012 年 5 月 31 日（**以較早者為準**）皆係真實且正確。", "a": "e392f90f4874"}, {"k": "tip", "t": "兩個設計重點：**①保證內容放在 Schedule 3**（本文只放宣告句，細目擺附件，這是股權買賣的標準做法）；**②雙時點**（簽約日＋完成日）——保證不是只在簽約那天真，交割那天也必須真，這叫 **repetition of warranties（保證重述）**。"}, {"k": "h1", "t": "(b) 賣方的揭露義務", "ic": "📢"}, {"k": "en", "sp": "(b) 立即揭露", "t": "(b) Vendor hereby agrees to disclose promptly to Purchaser in writing **upon being aware of** any event or circumstance which would arise or become known to it after the date of this Agreement and before Completion which:", "zh": "(b) 賣方據此合約同意在本合約簽訂之後但在完成日之前，若有發生任何事件或情事，且此事件或情事可…賣方會立即向買方以書面揭露：", "a": "52457a2ad82a"}, {"k": "en", "sp": "(i) 違反保證", "t": "(i) constitutes a breach of or is inconsistent with any of the Warranties; or", "zh": "(i) 構成「保證」之違反或與任何「保證」相牴觸時；或", "a": "9244da49b6c1"}, {"k": "en", "sp": "(ii) 重大不利", "t": "(ii) has a **material adverse effect** on the **financial condition** of the Company.", "zh": "(ii) 對標的公司的**財務狀況**有重大負面影響時。", "a": "b79154b62b88"}, {"k": "tip", "t": "**material adverse effect（MAE，重大不利影響）** 是併購合約最常吵的四個字。要注意三件事：怎麼定義「重大」？以什麼為衡量基準（財務狀況／營運／前景）？有沒有排除事項（carve-out，例如總體經濟、產業普遍性變動）？"}, {"k": "h1", "t": "(c) 買方的表述、保證及承諾", "ic": "🔄"}, {"k": "en", "sp": "(c) 買方表述", "t": "(c) Purchaser **represents, warrants and undertakes** to Vendor that as on the Completion Date and **at all times between the date hereof and the Completion Date**:", "zh": "(c) 買方向賣方於完成日（以及**於本合約簽訂日至完成日間任何時間**）**表述、保證及承諾**下列事項：", "a": "5a863036be91"}, {"k": "en", "sp": "(i) 權限與拘束力", "t": "(i) Each of the Purchaser or the Designated Subsidiary has the **legal right, power and authority** to **enter into, deliver and perform** this Agreement and any other documents given by it pursuant to or in connection with this Agreement, which when executed will constitute **legal, valid and binding obligations** of Purchaser, and enforceable against each of the Purchaser or the Designated Subsidiary in accordance with their respective terms.", "zh": "(i) 買方或任何**指定之子公司**皆有**合法權利、權力或授權**以**簽訂、交付或履行**本合約或依本合約交付之其他文件，且本合約或其他文件在訂定時皆係合法、有效且對買方具拘束力，同時可作為向買方或指定子公司依其條款強制執行。", "a": "d27e3fb3b776"}, {"k": "en", "sp": "(ii) 不牴觸", "t": "(ii) The execution, delivery and the performance by the Purchaser or the **Designated Subsidiary** of this Agreement will not (as applicable): (1) breach the **charter documents** of each of Purchaser and Designated Subsidiary; (2) **result in a violation under any applicable law**.", "zh": "(ii) 買方或指定子公司之執行、交付或履行本合約，並不會構成：(1) 違反買方或指定子公司之章程；及 (2) 不會導致違反任何適用的法律。", "a": "3207678f3d8e"}, {"k": "h1", "t": "書中解說", "ic": "💡"}, {"k": "p", "t": "於上述條款中，買賣雙方首先聲明於合約附件三中所為的陳述、保證或承諾皆係真實；其次，條款中約定，如果在合約簽署日後到交割完成日前，有違反保證或有其他重大不利的情況時，賣方必須立即以書面通知買方。", "a": "b09b0aca021a"}, {"k": "p", "t": "其三，買方同時也聲明，買方或其指定之受讓關係企業有權簽署、交付並履行本合約或以其為當事人一方之其他與本合約相關之文件，且本合約及該等文件構成對買方或其指定之受讓關係企業合法、有效並有拘束力之義務，並得依本合約或該等文件為強制執行；同時，買方或其關係企業在履行本合約時，不會違反任一公司的章程規定或違反任何相關法律。", "a": "e5e38449aa4f"}, {"k": "voc", "v": [{"w": "set out in Schedule 3", "pos": "phr.", "zh": "載於附件三", "syn": "specified in Schedule 3", "tip": "股權買賣的保證細目通常放附件，本文只留宣告句。別忘了翻附件——真正的風險都在那裡。", "trap": "", "a": "bce875926d44", "az": "c6a5f0291928"}, {"w": "collectively, the \"Warranties\"", "pos": "phr.", "zh": "合稱「保證」", "syn": "together, the …", "trap": "把 representations、warranties、undertakings 三者合併定義成一個詞，簡化後文；但也要注意這樣會不會混淆三者**不同的救濟效果**。", "tip": "", "a": "677392f363a1", "az": "8edf65850577"}, {"w": "true and accurate", "pos": "adj. phr.", "zh": "真實且正確", "syn": "true, accurate and not misleading", "tip": "加上 not misleading（無誤導）保護更周延，是買方律師會爭取的。", "trap": "", "a": "09c8867ab06a", "az": "caae873cb383"}, {"w": "as of the date of this Agreement and as of the Completion Date", "pos": "phr.", "zh": "於本合約簽訂之日及完成日", "trap": "**雙時點**：保證在簽約日與交割日都必須為真（repetition of warranties）。賣方會想只綁簽約日，買方會爭取綁雙時點。", "syn": "", "tip": "", "a": "b376d3667dcd", "az": "b6f4234634ce"}, {"w": "whichever is earlier", "pos": "phr.", "zh": "以較早者為準", "syn": "whichever is the later／whichever occurs first", "tip": "兩個時點並列時一定要寫清楚取哪一個。", "trap": "", "a": "98443191a949", "az": "ddbf64e7d5c0"}, {"w": "disclose promptly in writing", "pos": "v. phr.", "zh": "立即以書面揭露", "syn": "notify forthwith in writing", "tip": "揭露義務（disclosure obligation）；相對的概念是 disclosure letter（揭露函），賣方用它來排除已揭露事項的責任。", "trap": "", "a": "d97d2cb42e13", "az": "741139bb517c"}, {"w": "upon being aware of", "pos": "phr.", "zh": "於知悉時", "syn": "upon becoming aware of", "trap": "知悉標準要寫清楚：實際知悉（actual knowledge）還是應當知悉（constructive knowledge／after due enquiry）？差很多。", "tip": "", "a": "b7bbdd4bae1e", "az": "f3f30f6deaaa"}, {"w": "constitutes a breach of or is inconsistent with", "pos": "v. phr.", "zh": "構成…之違反或與…相牴觸", "tip": "兩個層次並列：直接違反＋雖未違反但相牴觸。", "syn": "", "trap": "", "a": "3eba780362e9", "az": "162f7c727bc7"}, {"w": "material adverse effect", "pos": "n. phr.", "zh": "重大不利（負面）影響", "syn": "MAE／MAC (material adverse change)", "trap": "併購合約最常吵的四個字。要看定義、衡量基準與 carve-out（排除總體經濟或產業普遍變動）。", "tip": "", "a": "83e72bdde90a", "az": "aad39921b56c"}, {"w": "financial condition", "pos": "n. phr.", "zh": "財務狀況", "syn": "business, assets, financial condition and prospects", "tip": "範圍寫越寬，買方越有機會主張 MAE。", "trap": "", "a": "7fd5afd3d63e", "az": "fed63776b201"}, {"w": "represents, warrants and undertakes", "pos": "v. phr.", "zh": "表述、保證及承諾", "tip": "三個動詞並列，等於同時啟動三條救濟路線。", "syn": "", "trap": "", "a": "7800960fa5c3", "az": "0d30886f0e86"}, {"w": "at all times between the date hereof and the Completion Date", "pos": "phr.", "zh": "於本合約簽訂日至完成日間任何時間", "trap": "比「雙時點」更嚴：**期間內隨時都必須為真**（continuing warranty）。", "syn": "", "tip": "", "a": "0a63da84c00a", "az": "335586a1f500"}, {"w": "legal right, power and authority", "pos": "n. phr.", "zh": "合法權利、權力或授權", "syn": "capacity and authority", "tip": "三件事：right（權利）、power（權能）、authority（授權）。英美合約的標準三連。", "trap": "", "a": "08de1a97305e", "az": "e9600d909379"}, {"w": "enter into, deliver and perform", "pos": "v. phr.", "zh": "簽訂、交付或履行", "syn": "execute, deliver and perform", "tip": "與解除條件單元的授權三部曲同一組。", "trap": "", "a": "faa6b96728ca", "az": "6ce18c72e696"}, {"w": "legal, valid and binding obligations", "pos": "n. phr.", "zh": "合法、有效且具拘束力之義務", "tip": "融資與併購合約的 capacity warranty 核心句；律師意見書（legal opinion）也是出這一句。", "syn": "", "trap": "", "a": "17e2e7f358d6", "az": "cf446b195c33"}, {"w": "enforceable in accordance with their respective terms", "pos": "adj. phr.", "zh": "得依其各自條款強制執行", "trap": "實務上這句後面常接一長串**例外**（subject to bankruptcy, insolvency and general principles of equity），要一併看。", "syn": "", "tip": "", "a": "3f0c05a51177", "az": "869ac6e456b6"}, {"w": "charter documents", "pos": "n. phr.", "zh": "公司章程（設立文件）", "syn": "constitutional documents／articles of association", "tip": "breach the charter documents＝違反章程。", "trap": "", "a": "4209f5f3fe86", "az": "d4d88279ceb3"}, {"w": "Designated Subsidiary", "pos": "n. phr.", "zh": "指定之子公司（受讓關係企業）", "tip": "買方常保留把交割主體換成集團內子公司的權利，所以保證要把它一起綁進來。", "syn": "", "trap": "", "a": "98bfb7bf79c3", "az": "dfa4703b06c3"}, {"w": "result in a violation under any applicable law", "pos": "v. phr.", "zh": "導致違反任何適用之法律", "syn": "contravene any applicable law", "tip": "no-conflict warranty（不牴觸保證）的標準寫法：不違章程、不違法、不違既有合約。", "trap": "", "a": "691be9eaa67f", "az": "7021568aab68"}]}]}, {"code": "3-5-3", "ch": "Chapter 參　基本條款", "sec": "五、表述、保證與承諾（Representation, Warranty, Undertaking）", "title": "例二：代工生產的表述及保證（買方 H／生產者 Manufacturer）", "items": [{"k": "lead", "t": "合約也可以分別針對雙方設計不同的表述及保證條款。本單元以代工生產（OEM）合約為例：買方 H 保證自己有權下單並持續授權商標；生產者則要保證產品無瑕疵、可銷售、不侵權、符合規格，還要遵守一長串美國產品法規並承諾不使用罪犯勞工、強迫勞動與童工。這一則是台廠最該讀熟的條款。"}, {"k": "h1", "t": "買方 H 的陳述", "ic": "🏢"}, {"k": "en", "sp": "H 保證及表述", "t": "H warrants and represents (a) that it **has and will have throughout the Term**, the **full power, authority and legal right** to execute and deliver this Agreement to perform fully and in accordance with all of the terms of this Agreement, and (b) that entering into this Agreement **does not violate any agreements, rights or obligations existing between** H and any other person, entity, or corporation.", "zh": "H 保證及表述：(a) 該公司**於合約存續期間內**將具有**完整之權力、授權及法律上權利**，以執行及交付本合約，以依合約約定完整履行其義務；且 (b) 簽訂本合約並未違反任何 H 與他人或其他機構或公司間之協議、權利或義務。", "a": "12bd1513fae4"}, {"k": "en", "sp": "商標授權", "t": "H warrants and represents that it has, and will have throughout the Term, **the right to authorize use of the Trademarks** to Manufacturer in accordance with the terms and provisions of this Agreement.", "zh": "H 同時保證及表述其將**於合約存續期間內**，具有授權生產者依本合約條款使用系爭商標之權利。", "a": "219de45a0223"}, {"k": "p", "t": "在上述條款中，買方保證及聲明買方將於合約存續期間內，保有完全的權力、授權及法律上權利以履行這個合約（這在涉及多數的買方當事人時係屬重要，以免有公司下訂單後拒絕履行）；同時，買方在簽訂此合約時，並沒有違反任何買方與其他人的合約（例如於獨家授權的情形，這種狀況有可能會出現）；此外，買方也保證及聲明在合約存續期間內，會持續將買方的商標授權予生產者以供其生產之用。"}, {"k": "tip", "t": "為求精確，於**時態**上其用語有包括現在及未來式（例「**has and will have**」）。這是英文合約的重要技巧：保證不只「現在是」，而且「整個合約期間都會是」（throughout the Term）。"}, {"k": "h1", "t": "生產者的陳述・權限", "ic": "🏭"}, {"k": "en", "sp": "生產者保證", "t": "Manufacturer warrants and represents: (a) that it **has and will have throughout the Term**, the **full power, authority and legal right** to execute and deliver, and to perform fully and in accordance with all of the terms of this Agreement, and (b) that its entering into this Agreement by Manufacturer **does not violate any agreements, rights or obligations existing between** Manufacturer and any other person, entity, or corporation.", "zh": "生產者保證及表述下列事項：(a) 其**於合約存續期間內**，擁有完整之權力、授權或法律上權利，以執行及交付本合約，依合約約定完整履行其義務；及 (b) 簽訂本合約並未違反任何生產者與他人或其他機構或公司間之協議、權利或義務。", "a": "4f83ae58f7b3"}, {"k": "h1", "t": "生產者的陳述・產品保證", "ic": "📦"}, {"k": "en", "sp": "產品五大保證", "t": "Manufacturer warrants and represents, **on behalf of itself and its affiliates**, that **in addition to all warranties implied by law**, that the Products, together with all related packaging, labeling furnished or authorized by Manufacturer shall", "zh": "生產者同時**代表其自己及其關係企業**，表述及保證其**除法律上所隱含**的保證之外，契約標的產品（包括由生產者所提供之包裝或標籤等）應符合下列事項：", "a": "e2219545a40a"}, {"k": "en", "sp": "(a) 無瑕疵", "t": "(a) be **free from defects in design, workmanship or materials** **including, without limitation**, such defects as could **create a hazard to life or property**;", "zh": "(a) 設計、生產或其質料上無任何瑕疵，包括（但不限於）可能造成生命或財產損害之瑕疵；", "a": "26f32434289e"}, {"k": "en", "sp": "(b) 可銷售品質", "t": "(b) be of **merchantable quality** and **fit for H's purposes and suitable for use**, manufactured, packed for and **marked with the country of origin**, in accordance with all applicable laws of the destination country and all orders and regulations promulgated there under;", "zh": "(b) 且**可銷售**的品質，且符合 H 生產此產品之目的，且適於被使用、生產、包裝或產地標示，並符合所有**目的地國家**所適用的法律（包括命令及規則）；", "a": "f7ad6250e6ee"}, {"k": "en", "sp": "(c) 不侵權", "t": "(c) not **infringe or encroach upon** any third parties' personal, contractual or **proprietary rights**, **including, without limitation**, any third party Intellectual Property;", "zh": "(c) 未侵害任何第三人個人、合約或**財產上**之權利，包括（但不限於）第三人之智慧財產權；", "a": "fa47b4f7789b"}, {"k": "en", "sp": "(d) 符合規格", "t": "(d) **conform to all specifications** and other descriptions set forth or incorporated herein and all articles accepted by H as **Product samples**; and", "zh": "(d) 符合由 H 指定或由 H 所接受的樣本的規格或描述；以及", "a": "87481032dadb"}, {"k": "en", "sp": "(e) 符合廣告", "t": "(e) possess all performance qualities and characteristics claimed in advertisements issued by Manufacturer.", "zh": "(e) 擁有生產者於其廣告所宣示具有之品質及特色。", "a": "476b5239df5f"}, {"k": "tip", "t": "產品保證的五支箭：**無瑕疵／可銷售（merchantable）／不侵權／符合規格樣本／符合廣告宣稱**。注意開頭那句 **in addition to all warranties implied by law**——法定的默示保證仍然存在，契約保證是「加上去」而不是取代。"}, {"k": "h1", "t": "生產者的陳述・法遵與勞工", "ic": "⚖️"}, {"k": "en", "sp": "美國法規遵循", "t": "Manufacturer **on behalf of itself and its affiliates** represents and warrants that they are in compliance with and covenants that they shall continue to comply with the following United States statutes: the Wool Products Labeling Act, Textile Fiber Products Identification Act, Fur Products Labeling Act, Hazardous Substances Act, Toy Safety Act, Consumer Products Safety Act, Flammable Fabrics Act, Fair Packaging and Labeling Act and the Food, Drug and Cosmetics Act", "zh": "生產者同時**代表其自己及其關係企業**，表述及保證其將會遵守下列美國的法令：羊毛產品標示法、紡織品纖維產品辨識法、皮革產品標示法、危險物質法、玩具安全法、消費者產品安全法、可燃織品法、公平包裝及標示法以及食物、藥物及化妝品法；", "a": "3812033ac93c"}, {"k": "en", "sp": "勞工保證", "t": "and warrants that convict labor, forced labor, child labor and/or indentured labor under penal sanctions was not and will not be employed, **in whole or in part, in any stage of the production** or manufacture of Products or components thereof.", "zh": "並保證於生產契約標的產品或任何零組件之任何階段，並不會僱用罪犯勞工、強迫勞動、童工或其他非法之勞工。", "a": "e29ff02146fe"}, {"k": "en", "sp": "效力保留", "t": "Manufacturer's representations and warranties herein shall survive the delivery of the Products to H, its subsidiaries and affiliates, and any resale of the Products by H, its subsidiaries or affiliates, as well as expiration or termination of this Agreement and shall continue in effect **until the applicable statute of limitations expires**.", "zh": "生產者之表述及保證，不因將產品交付予 H 或其子公司或其關係企業，或因本合約到期或被終止而失其效力，且將持續有效**至相關法令之時效消滅為止**。", "a": "a435123029fb"}, {"k": "tip", "t": "最後這一句就是**效力保留條款**在表述保證上的應用（見 3-4-4）：保證不因交貨、不因轉售、不因合約終止而消滅，而是一路延續到**法定時效屆滿**為止。對台灣代工廠而言，這是風險最長尾的一句話。"}, {"k": "voc", "v": [{"w": "has and will have throughout the Term", "pos": "phr.", "zh": "於合約存續期間內（現在）具有且（未來）將持續具有", "trap": "書中特別點名的**時態技巧**：為求精確，用語同時包括現在式與未來式。只寫 has 的話，期間內變動就不在保證範圍。", "syn": "", "tip": "", "a": "b5eb5a6a8b9f", "az": "52796159107f"}, {"w": "full power, authority and legal right", "pos": "n. phr.", "zh": "完整之權力、授權及法律上權利", "syn": "legal right, power and authority", "tip": "與股份買賣例的 capacity warranty 同一組句型。", "trap": "", "a": "70c45a72d1e5", "az": "0d14732836ec"}, {"w": "does not violate any agreements, rights or obligations existing between", "pos": "v. phr.", "zh": "並未違反…與他人間現存之協議、權利或義務", "trap": "no-conflict warranty 的第三支：不違反**既有合約**。書中提醒：於**獨家授權**的情形，這種衝突很可能出現。", "syn": "", "tip": "", "a": "dccca8f898a2", "az": "d3908c2b4349"}, {"w": "the right to authorize use of the Trademarks", "pos": "n. phr.", "zh": "授權使用（系爭）商標之權利", "tip": "代工合約的命脈：品牌方必須保證它真的有權把商標授權下去，否則代工廠生產就是侵權。", "syn": "", "trap": "", "a": "84e150fa95c6", "az": "06b4f93d8b2e"}, {"w": "on behalf of itself and its affiliates", "pos": "phr.", "zh": "代表其自己及其關係企業", "trap": "把集團一起綁進保證，責任範圍大幅擴張。代工廠談判時要注意 affiliates 的定義。", "syn": "", "tip": "", "a": "fb253aeb076d", "az": "06fbabf8e125"}, {"w": "in addition to all warranties implied by law", "pos": "phr.", "zh": "除法律上所隱含（默示）的保證之外", "syn": "implied warranties", "trap": "相對的概念是 **disclaimer of implied warranties**（排除默示保證）。本條反過來寫：契約保證是**加在**法定默示保證之上。", "tip": "", "a": "27a9a30b6974", "az": "4508fd8ec462"}, {"w": "free from defects in design, workmanship or materials", "pos": "adj. phr.", "zh": "設計、作工或材料上無瑕疵", "tip": "產品責任的三種瑕疵分類，背起來。", "syn": "", "trap": "", "a": "3421f91542d0", "az": "b286ec5c333c"}, {"w": "including, without limitation", "pos": "phr.", "zh": "包括但不限於", "syn": "including but not limited to", "tip": "避免被解為窮盡列舉。與 means／includes 那組觀念一起記。", "trap": "", "a": "39a12f830bf7", "az": "0c826bb94eec"}, {"w": "create a hazard to life or property", "pos": "v. phr.", "zh": "造成生命或財產之危害", "syn": "safety hazard", "tip": "把安全瑕疵特別點名，是產品責任條款的重點。", "trap": "", "a": "975ab44833c9", "az": "5084c0e6080f"}, {"w": "merchantable quality", "pos": "n. phr.", "zh": "可銷售（適銷）品質", "syn": "satisfactory quality（英國 1994 年後用語）", "trap": "英美法的默示保證之一。另一個是 fitness for purpose（適於特定目的）——本條兩個都寫了。", "tip": "", "a": "dedd687c2c9b", "az": "1a0ef1839c5d"}, {"w": "fit for H's purposes and suitable for use", "pos": "adj. phr.", "zh": "符合 H 之目的且適於使用", "syn": "fitness for a particular purpose", "tip": "買方有特殊用途時務必寫明，否則只能主張一般用途。", "trap": "", "a": "de9d2e4b0f30", "az": "b6e30195886c"}, {"w": "marked with the country of origin", "pos": "v. phr.", "zh": "標示產地", "syn": "country of origin marking", "tip": "美國海關對產地標示要求嚴格，標錯會被扣關。", "trap": "", "a": "7ab35da65ff4", "az": "6a3bc71b2889"}, {"w": "destination country", "pos": "n. phr.", "zh": "目的地國家", "tip": "法遵的基準是**目的地國**的法律與其下的命令及規則，不是生產國。", "syn": "", "trap": "", "a": "de10ff60a264", "az": "cad829d9bbf2"}, {"w": "promulgated thereunder", "pos": "v. phr.", "zh": "依該法所頒布之（命令規則）", "tip": "thereunder＝under that（法律）。法規＋其子法一併納入。", "syn": "", "trap": "", "a": "cfb2de4830f2", "az": "5a4fbecf6e04"}, {"w": "infringe or encroach upon", "pos": "v. phr.", "zh": "侵害或侵犯", "syn": "violate／misappropriate", "tip": "兩個動詞並列求周延。", "trap": "", "a": "b9bc72c7e766", "az": "644196a91e0e"}, {"w": "proprietary rights", "pos": "n. phr.", "zh": "財產上（專有）之權利", "syn": "Intellectual Property Rights", "tip": "包含智財、營業秘密等專有權利。", "trap": "", "a": "32573f3244e0", "az": "6a860af3a7ce"}, {"w": "conform to all specifications", "pos": "v. phr.", "zh": "符合所有規格", "syn": "comply with the specifications", "tip": "代工合約的驗收基準，常再連結到 Product samples（樣品）。", "trap": "", "a": "a2e42d9e5bd9", "az": "391a3577bcdf"}, {"w": "Product samples", "pos": "n. phr.", "zh": "產品樣本（樣品）", "tip": "all articles accepted by H as Product samples＝由 H 接受為樣品之物品。樣品確認書是實務上的關鍵證據。", "syn": "", "trap": "", "a": "09b95c91f148", "az": "efbf34543820"}, {"w": "performance qualities and characteristics claimed in advertisements", "pos": "n. phr.", "zh": "廣告所宣稱之品質及特色", "trap": "廣告也會變成保證內容——這是行銷部門最常忽略的法律風險。", "syn": "", "tip": "", "a": "0fb18079f875", "az": "16f2f13cc301"}, {"w": "convict labor / forced labor / child labor / indentured labor", "pos": "n. phr.", "zh": "罪犯勞工／強迫勞動／童工／債務勞工", "trap": "美國關稅法 §307 禁止進口以強迫勞動製造的商品（UFLPA 更進一步）。供應鏈 ESG 盡職調查的核心條款，台廠必讀。", "syn": "", "tip": "", "a": "e8cc1c111660", "az": "ac7963716b52"}, {"w": "in whole or in part, in any stage of the production", "pos": "phr.", "zh": "於生產之任何階段，全部或一部", "tip": "把整條供應鏈的每個階段都包進來。", "syn": "", "trap": "", "a": "17efd04f6477", "az": "d3090365c37a"}, {"w": "shall survive the delivery / any resale / expiration or termination", "pos": "v. phr.", "zh": "不因交付、轉售或合約期滿終止而失效", "tip": "效力保留條款在表述保證上的應用，見 3-4-4 單元。", "syn": "", "trap": "", "a": "0a90d5d2971d", "az": "de7747eef16f"}, {"w": "until the applicable statute of limitations expires", "pos": "phr.", "zh": "至相關法令之時效消滅為止", "trap": "保證期間一路延伸到**法定時效屆滿**，是風險最長尾的寫法。代工廠談判時應爭取訂明具體年限。", "syn": "", "tip": "", "a": "881bc04343dc", "az": "4d7f6ad069d2"}]}]}];